consumers.resolutionPolicy:
() => { if (hardware.DisplayWidth is int width && hardware.DisplayHeight is int height) { if (new Engine().Adapter(configuration) is IEmulatorVideoSettings video && video.GetOutputResolution(configuration) is { } resolution)
            {
                width = resolution.Width;
                height = resolution.Height;
            } return $"{width} × {height}"; } return null; }

