internal void Enqueue(AudioChunk chunk)
    {
        lock (_gate)
        {
            var maximumFrames = AudioFunctions.MaximumBufferedFrames(chunk.SampleRate);
            var retained = AudioFunctions.RetainNewestFrames(chunk, maximumFrames);
