private void HandleAudioSample(short left, short right)
    {
        PublishAudio(new AudioChunk(new[] { left, right }, SampleRate, AudioConstants.SingleFrameCount, ++_audioSequence, _clock.Elapsed));
    }

private nuint HandleAudioBatch(nint data, nuint frames)
    {
        if (data == nint.Zero || frames == ExternalCoreInteropConstants.EmptyNativeSize) return frames;
        var samples = new short[checked((int)frames * AudioConstants.StereoChannelCount)];
        Marshal.Copy(data, samples, BufferConstants.FirstBufferIndex, samples.Length);
        PublishAudio(new AudioChunk(samples, SampleRate, checked((int)frames), ++_audioSequence, _clock.Elapsed));
        return frames;
    }

private void PublishAudio(AudioChunk chunk)
    {
        LatestAudioChunk = chunk;
        lock (_audioGate)
        {
            var maximumFrames = Math.Max(AudioConstants.MinimumBufferedFrameCount, SampleRate / AudioConstants.BufferDurationDivisor);
            if (chunk.FrameCount > maximumFrames)
            {
                var retainedSamples = chunk.InterleavedSamples.Slice((chunk.FrameCount - maximumFrames) * AudioConstants.StereoChannelCount).ToArray();
                chunk = new AudioChunk(retainedSamples, chunk.SampleRate, maximumFrames, chunk.Sequence, chunk.Timestamp);
                AudioOverrunCount++;
            }
            _audioChunks.Enqueue(chunk);
            _bufferedAudioFrames += chunk.FrameCount;
            while (_bufferedAudioFrames > maximumFrames && _audioChunks.Count > AudioConstants.MinimumBufferedFrameCount)
            {
                _bufferedAudioFrames -= _audioChunks.Dequeue().FrameCount;
                AudioOverrunCount++;
            }
        }
    }

internal bool TryDequeueAudio(out AudioChunk? chunk)
    {
        lock (_audioGate)
        {
            if (!_audioChunks.TryDequeue(out chunk)) return false;
            _bufferedAudioFrames -= chunk.FrameCount;
            return true;
        }
    }

public void Dispose()
    {
        if (_disposed) return;
        try
        {
            foreach (var pointer in _nativeStrings.Values)
            {
                try { pointer.Dispose(); }
                catch (Exception) { }
            }
        }
        finally
        {
            _nativeStrings.Clear();
            _keyboardEvent = null;
            _updateOptionsDisplay = null;
            LatestVideoFrame = null;
            lock (_audioGate)
            {
                _audioChunks.Clear();
                _bufferedAudioFrames = BufferConstants.EmptyCollectionCount;
                LatestAudioChunk = null;
            }
            lock (_inputGate)
            {
                _pendingInput = EmulationInputSnapshot.Empty;
                _polledInput = EmulationInputSnapshot.Empty;
                _previousKeys = new HashSet<EmulationKey>();
            }
            _disposed = true;
        }
    }

