    {
        if (data == nint.Zero || frames == ExternalCoreInteropConstants.EmptyNativeSize) return frames;
        var samples = new short[checked((int)frames * 2)];
        Marshal.Copy(data, samples, BufferConstants.FirstBufferIndex, samples.Length);
