using GWGUI.Infrastructure.Hardware.Media;

namespace GWGUI.App.Services.PhysicalDiskWriting;

public sealed class PhysicalDiskWriteService(MediaPhysicalWriterRegistry writers)
{
    public async Task<PhysicalDiskWriteResult> WriteAsync(MediaWritePlan plan, PhysicalDiskWriteOptions options, IProgress<PhysicalTrackWriteProgress>? progress = null, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(plan);
        ArgumentNullException.ThrowIfNull(options);
        if (string.IsNullOrWhiteSpace(options.PortName) || options.Verify)
        {
            var failure = new PhysicalTrackWriteFailure(null, null, PhysicalDiskWriteFailureCategory.Validation);
            return new PhysicalDiskWriteResult(0, plan.WriteOrder.Count, false, [failure]);
        }
        var writeProgress = new Progress<MediaPhysicalWriteProgress>(value => ReportProgress(plan, value, progress));
        var result = await writers.WriteAsync(plan, options.PortName, CreateOptions(options), writeProgress, cancellationToken).ConfigureAwait(false);
        var failures = result.Diagnostics.Select(MapFailure).ToArray();
        return new PhysicalDiskWriteResult(result.CompletedUnits, result.TotalUnits, result.Cancelled, failures);
    }

    private static IReadOnlyDictionary<string, string> CreateOptions(PhysicalDiskWriteOptions options) =>
        new Dictionary<string, string>(StringComparer.Ordinal)
        {
            [GreaseweazleMediaOptionKeys.BusType] = options.BusType.ToString(),
            [GreaseweazleMediaOptionKeys.DriveUnit] = options.DriveUnit.ToString(CultureInfo.InvariantCulture),
            [GreaseweazleMediaOptionKeys.CueAtIndex] = options.CueAtIndex.ToString(CultureInfo.InvariantCulture),
            [GreaseweazleMediaOptionKeys.TerminateAtIndex] = options.TerminateAtIndex.ToString(CultureInfo.InvariantCulture),
            [GreaseweazleMediaOptionKeys.HardSectorTicks] = options.HardSectorTicks.ToString(CultureInfo.InvariantCulture)
        };

    private static void ReportProgress(MediaWritePlan plan, MediaPhysicalWriteProgress value, IProgress<PhysicalTrackWriteProgress>? progress)
    {
        var unit = plan.DataUnits.FirstOrDefault(item => item.Position == value.Position);
        var cylinder = unit is null ? 0 : ReadPosition(unit.Metadata, MediaPhysicalMetadataKeys.Cylinder);
        var head = unit is null ? 0 : ReadPosition(unit.Metadata, MediaPhysicalMetadataKeys.Head);
        var tracks = plan.DataUnits.Select(item => new PhysicalTrackWriteAddress(ReadPosition(item.Metadata, MediaPhysicalMetadataKeys.Cylinder), ReadPosition(item.Metadata, MediaPhysicalMetadataKeys.Head))).Distinct()
            .OrderBy(item => item.Cylinder)
            .ThenBy(item => item.Head)
            .ToArray();
        progress?.Report(new PhysicalTrackWriteProgress(value.CompletedUnits, value.TotalUnits, cylinder, head, value.Verifying, tracks));
    }

    private static int ReadPosition(IReadOnlyDictionary<string, string> metadata, string key) => metadata.TryGetValue(key, out var value) && int.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed) ? parsed : 0;

    private static PhysicalTrackWriteFailure MapFailure(string diagnostic)
    {
        var category = diagnostic.Contains("WriteProtected", StringComparison.OrdinalIgnoreCase) || diagnostic.Contains("write protected", StringComparison.OrdinalIgnoreCase) ? PhysicalDiskWriteFailureCategory.WriteProtected : PhysicalDiskWriteFailureCategory.Device;
        return new PhysicalTrackWriteFailure(null, null, category, new IOException(diagnostic));
    }
}

using System.Globalization;
using MediaPhysicalEncodingIds = global::GWGUI.MediaEngine.Constants.MediaPhysicalEncodingIds;
using MediaPhysicalMetadataKeys = global::GWGUI.MediaEngine.Constants.MediaPhysicalMetadataKeys;
using MediaAcquisitionResult = global::GWGUI.MediaEngine.Contracts.MediaAcquisitionResult;
using MediaPhysicalDataUnit = global::GWGUI.MediaEngine.Contracts.MediaPhysicalDataUnit;
using GWGUI.MediaEngine.Enums;
using GWGUI.MediaEngine.Functions;
using GWGUI.MediaEngine.Images.Formats.Floppy.Scp;

namespace GWGUI.MediaEngine.Images.Formats.Floppy.Scp.Reading;

/// <summary>Reconstructs MediaEngine SCP data from neutral physical floppy flux units.</summary>
public sealed class FloppyFluxAcquisitionService
{
    public ScpImage CreateScpImage(MediaAcquisitionResult acquisition)
    {
        ArgumentNullException.ThrowIfNull(acquisition);
        if (acquisition.MediaKind != MediaKind.Floppy || acquisition.RepresentationKind != MediaRepresentationKind.Flux)
            throw new NotSupportedException("A floppy flux acquisition is required to construct an SCP image.");
        if (acquisition.DataUnits.Count == 0)
            throw new InvalidDataException("The physical acquisition contains no flux track.");

        var tracks = acquisition.DataUnits.Select(CreateTrack).OrderBy(track => track.TrackNumber).ToArray();
        if (tracks.Select(track => track.TrackNumber).Distinct().Count() != tracks.Length)
            throw new InvalidDataException("The physical acquisition contains a duplicate floppy track.");
        var revolutionCount = tracks[0].Revolutions.Count;
        if (revolutionCount is < ScpFormatConstants.MinimumRevolutionCount or > ScpFormatConstants.MaximumRevolutionCount
            || tracks.Any(track => track.Revolutions.Count != revolutionCount))
            throw new InvalidDataException("Every acquired floppy track must contain the same supported revolution count.");
        var diskType = ReadDiskType(acquisition.Metadata);
        var header = new ScpHeader(
            ScpFormatConstants.InternalCaptureVersion,
            (byte)diskType,
            checked((byte)revolutionCount),
            tracks.Min(track => track.TrackNumber),
            tracks.Max(track => track.TrackNumber),
            ScpFlags.IndexAligned | ScpFlags.Writable | ScpFlags.ThirdPartyCreator,
            ScpBitCellEncoding.Default16Bit,
            ResolveHeads(tracks),
            ScpFormatConstants.InternalCaptureResolution,
            ScpFormatConstants.MissingChecksum);
        return new ScpImage(header, tracks, false, 0);
    }

    public ScpTrack CreateTrack(MediaPhysicalDataUnit unit)
    {
        ArgumentNullException.ThrowIfNull(unit);
        if (!unit.Metadata.TryGetValue(MediaPhysicalMetadataKeys.Encoding, out var encoding)
            || !encoding.Equals(MediaPhysicalEncodingIds.FluxTrackV1, StringComparison.Ordinal))
            throw new InvalidDataException("The physical data unit is not a supported neutral flux track.");
        var cylinder = ReadInt(unit.Metadata, MediaPhysicalMetadataKeys.Cylinder);
        var head = ReadInt(unit.Metadata, MediaPhysicalMetadataKeys.Head);
        var trackData = MediaFluxTrackDataFunctions.Deserialize(unit.Data.Span);
        var resolutionNanoseconds = ScpFormatConstants.ResolutionStepNanoseconds * (ScpFormatConstants.InternalCaptureResolution + ScpFormatConstants.ResolutionIndexOffset);
        var revolutions = trackData.Revolutions.Select(revolution =>
        {
            var intervals = ConvertNanoseconds(revolution.FluxIntervalsNanoseconds, resolutionNanoseconds);
            var indexTime = ConvertNanoseconds(revolution.IndexTimeNanoseconds, resolutionNanoseconds);
            return new ScpRevolution(indexTime, checked((uint)intervals.Count), intervals);
        }).ToArray();
        return new ScpTrack(ScpFormatConstants.ToTrackNumber(cylinder, head), cylinder, head, revolutions);
    }

    private static IReadOnlyList<uint> ConvertNanoseconds(IReadOnlyList<uint> intervalsNanoseconds, int resolutionNanoseconds)
    {
        var result = new uint[intervalsNanoseconds.Count];
        ulong sourceElapsed = 0;
        ulong targetElapsed = 0;
        for (var index = 0; index < intervalsNanoseconds.Count; index++)
        {
            sourceElapsed += intervalsNanoseconds[index];
            var convertedElapsed = (ulong)Math.Round(sourceElapsed / (double)resolutionNanoseconds);
            if (convertedElapsed <= targetElapsed)
                throw new InvalidDataException("A neutral flux interval is shorter than the selected SCP resolution.");
            result[index] = checked((uint)(convertedElapsed - targetElapsed));
            targetElapsed = convertedElapsed;
        }
        return result;
    }

    private static uint ConvertNanoseconds(uint nanoseconds, int resolutionNanoseconds) => checked((uint)Math.Max(1, Math.Round(nanoseconds / (double)resolutionNanoseconds)));

    private static int ReadInt(IReadOnlyDictionary<string, string> metadata, string key) =>
        metadata.TryGetValue(key, out var value) && int.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed) ? parsed : throw new InvalidDataException($"Physical acquisition metadata '{key}' is missing or invalid.");

    private static ScpDiskType ReadDiskType(IReadOnlyDictionary<string, string> metadata)
    {
        if (!metadata.TryGetValue(MediaPhysicalMetadataKeys.DiskType, out var value))
            throw new InvalidDataException("Physical acquisition disk-type metadata is missing.");
        if (Enum.TryParse<ScpDiskType>(value, true, out var named)) return named;
        if (byte.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out var numeric)
            && Enum.IsDefined(typeof(ScpDiskType), numeric)) return (ScpDiskType)numeric;
        throw new InvalidDataException($"Physical acquisition disk type '{value}' is invalid.");
    }

    private static ScpHeadSelection ResolveHeads(IReadOnlyList<ScpTrack> tracks)
    {
        var head0 = tracks.Any(track => track.Head == 0);
        var head1 = tracks.Any(track => track.Head == 1);
        return (head0, head1) switch
        {
            (true, true) => ScpHeadSelection.Both,
            (true, false) => ScpHeadSelection.Side0,
            (false, true) => ScpHeadSelection.Side1,
            _ => throw new InvalidDataException("The physical acquisition contains no supported floppy head.")
        };
    }
}

using System.Collections.Frozen;
using System.Globalization;
using MediaPhysicalEncodingIds = global::GWGUI.MediaEngine.Constants.MediaPhysicalEncodingIds;
using MediaPhysicalMetadataKeys = global::GWGUI.MediaEngine.Constants.MediaPhysicalMetadataKeys;
using MediaPhysicalDataUnit = global::GWGUI.MediaEngine.Contracts.MediaPhysicalDataUnit;
using MediaPhysicalWriteProgress = global::GWGUI.MediaEngine.Contracts.MediaPhysicalWriteProgress;
using MediaPhysicalWriteResult = global::GWGUI.MediaEngine.Contracts.MediaPhysicalWriteResult;
using MediaWritePlan = global::GWGUI.MediaEngine.Contracts.MediaWritePlan;
using GWGUI.MediaEngine.Enums;
using GWGUI.MediaEngine.Functions;
