using GWGUI.Infrastructure.Constants;

namespace GWGUI.Infrastructure.Hardware.Greaseweazle;

/// <summary>Writes neutral floppy flux plans through a Greaseweazle device.</summary>
public sealed class GreaseweazleMediaPhysicalWriter(Func<IGreaseweazleWriteDevice> deviceFactory) : IMediaPhysicalWriter
{
    private static readonly IReadOnlySet<MediaKind> MediaKinds = new[] { MediaKind.Floppy }.ToFrozenSet();

    public string Id => GreaseweazleProtocol.MediaProviderId;

    public IReadOnlySet<MediaKind> SupportedMediaKinds => MediaKinds;

    public bool CanWrite(MediaWritePlan plan, string deviceId)
    {
        ArgumentNullException.ThrowIfNull(plan);
        return plan.MediaKind == MediaKind.Floppy
            && plan.RepresentationKind == MediaRepresentationKind.Flux
            && !string.IsNullOrWhiteSpace(deviceId)
            && plan.DataUnits.Count > 0
            && plan.DataUnits.All(unit => unit.Metadata.TryGetValue(MediaPhysicalMetadataKeys.Encoding, out var encoding) && encoding.Equals(MediaPhysicalEncodingIds.FluxTrackV1, StringComparison.Ordinal));
    }

    public async Task<MediaPhysicalWriteResult> WriteAsync(
        MediaWritePlan plan,
        string deviceId,
        IReadOnlyDictionary<string, string> options,
        IProgress<MediaPhysicalWriteProgress>? progress = null,
        CancellationToken cancellationToken = default)
    {
        if (!CanWrite(plan, deviceId))
            throw new NotSupportedException("Greaseweazle requires a neutral floppy flux write plan.");
        ArgumentNullException.ThrowIfNull(options);
        var busType = GreaseweazleMediaOptionFunctions.ReadEnum<GreaseweazleBusType>(options, GreaseweazleMediaOptionKeys.BusType);
        var driveUnit = checked((byte)ReadInt(options, GreaseweazleMediaOptionKeys.DriveUnit));
        var cueAtIndex = ReadBool(options, GreaseweazleMediaOptionKeys.CueAtIndex, true);
        var terminateAtIndex = ReadBool(options, GreaseweazleMediaOptionKeys.TerminateAtIndex, true);
        var hardSectorTicks = checked((uint)ReadLong(options, GreaseweazleMediaOptionKeys.HardSectorTicks, 0));
        var completed = 0;
        var diagnostics = new List<string>();

        await using var device = deviceFactory();
        try
        {
            var firmware = await device.OpenAsync(deviceId, cancellationToken).ConfigureAwait(false);
            await device.SetBusTypeAsync(busType, cancellationToken).ConfigureAwait(false);
            await device.SelectDriveAsync(driveUnit, cancellationToken).ConfigureAwait(false);
            await device.SetMotorAsync(true, cancellationToken).ConfigureAwait(false);
            foreach (var unitIndex in plan.WriteOrder)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var unit = plan.DataUnits[unitIndex];
                var cylinder = ReadMetadataInt(unit, MediaPhysicalMetadataKeys.Cylinder);
                var head = ReadMetadataInt(unit, MediaPhysicalMetadataKeys.Head);
                var track = MediaFluxTrackDataFunctions.Deserialize(unit.Data.Span);
                if (track.Revolutions.Count != 1)
                    throw new InvalidDataException("A physical write unit must contain exactly one selected flux revolution.");
                await device.SeekAsync(checked((short)cylinder), checked((byte)head), cancellationToken).ConfigureAwait(false);
                var intervals = ConvertNanosecondsToDeviceTicks(track.Revolutions[0].FluxIntervalsNanoseconds, firmware.SampleFrequency);
                await device.WriteFluxAsync(intervals, cueAtIndex, terminateAtIndex, hardSectorTicks, cancellationToken).ConfigureAwait(false);
                completed++;
                progress?.Report(new MediaPhysicalWriteProgress(completed, plan.WriteOrder.Count, unit.Position, false));
            }
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            return new MediaPhysicalWriteResult(completed, plan.WriteOrder.Count, true, diagnostics);
        }
        catch (Exception exception)
        {
            diagnostics.Add($"{exception.GetType().Name}: {exception.Message}");
        }
        finally
        {
            try
            {
                await device.CloseAsync(CancellationToken.None).ConfigureAwait(false);
            }
            catch (Exception exception)
            {
                diagnostics.Add($"{exception.GetType().Name}: {exception.Message}");
            }
        }
        return new MediaPhysicalWriteResult(completed, plan.WriteOrder.Count, false, diagnostics);
    }

    private static uint[] ConvertNanosecondsToDeviceTicks(IReadOnlyList<uint> intervalsNanoseconds, uint sampleFrequency)
    {
        var result = new uint[intervalsNanoseconds.Count];
        ulong sourceElapsed = 0;
        ulong targetElapsed = 0;
        for (var index = 0; index < intervalsNanoseconds.Count; index++)
        {
            sourceElapsed += intervalsNanoseconds[index];
            var convertedElapsed = (ulong)Math.Round(sourceElapsed * sampleFrequency / 1_000_000_000d);
            if (convertedElapsed <= targetElapsed)
                throw new InvalidDataException("A neutral flux interval is shorter than one Greaseweazle sample tick.");
            result[index] = checked((uint)(convertedElapsed - targetElapsed));
            targetElapsed = convertedElapsed;
        }
        return result;
    }

    private static int ReadMetadataInt(MediaPhysicalDataUnit unit, string key) =>
        unit.Metadata.TryGetValue(key, out var value) && int.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed) ? parsed : throw new InvalidDataException($"Physical write metadata '{key}' is missing or invalid.");

    private static int ReadInt(IReadOnlyDictionary<string, string> options, string key) =>
        int.TryParse(GreaseweazleMediaOptionFunctions.ReadRequired(options, key), NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed) ? parsed : throw new ArgumentException($"Invalid integer value for option '{key}'.", nameof(options));

    private static long ReadLong(IReadOnlyDictionary<string, string> options, string key, long defaultValue) =>
        !options.TryGetValue(key, out var value) ? defaultValue : long.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed) ? parsed : throw new ArgumentException($"Invalid integer value for option '{key}'.", nameof(options));

    private static bool ReadBool(IReadOnlyDictionary<string, string> options, string key, bool defaultValue) =>
        !options.TryGetValue(key, out var value) ? defaultValue : bool.TryParse(value, out var parsed) ? parsed : throw new ArgumentException($"Invalid Boolean value for option '{key}'.", nameof(options));
}

using System.Collections.Frozen;
using System.Globalization;
using GWGUI.MediaEngine.Enums;
using GWGUI.MediaEngine.Constants;
using GWGUI.MediaEngine.Contracts;

using GWGUI.MediaEngine.Functions;
using GWGUI.MediaEngine.Interfaces.Decoding;
using GWGUI.MediaEngine.Images.Reading.Recognition;
using GWGUI.MediaEngine.Images.Models.Sequential;

namespace GWGUI.MediaEngine.Images.Reading.Decoding.Sequential.Commodore;

/// <summary>Recognizes standard Commodore ROM byte frames in TAP pulses or a selected PCM WAV channel.</summary>
public sealed class CommodoreTapeDecoder : ISequentialMediaDecoder
{
    private static readonly IReadOnlySet<string> SupportedFormats = new[] { TapeImageFormatIds.CommodoreTap, TapeImageFormatIds.Wav }.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
    private static readonly IReadOnlySet<string> SupportedMachines = new[] { DiskSystemIds.Commodore }.ToFrozenSet(StringComparer.OrdinalIgnoreCase);

    public string Id => CommodoreTapConstants.DecoderId;
    public IReadOnlySet<string> FormatIds => SupportedFormats;
    public IReadOnlySet<string> MachineIds => SupportedMachines;

    public bool CanDecode(MediaImageDocument document, string? machineId = null) => document.MediaKind == MediaKind.Tape && SupportedFormats.Contains(document.FormatId) && (machineId is null || SupportedMachines.Contains(machineId)) && document.Representation is SequentialMediaImageRepresentation;

    public async Task<SequentialDecodeResult> DecodeAsync(MediaImageDocument document, string? machineId = null, CancellationToken cancellationToken = default)
    {
        if (!CanDecode(document, machineId))
            throw new InvalidDataException("The media document is not compatible with the Commodore tape decoder.");
        var representation = (SequentialMediaImageRepresentation)document.Representation;
        if (document.FormatId.Equals(TapeImageFormatIds.Wav, StringComparison.OrdinalIgnoreCase))
            return await DecodeWaveAsync(document, representation, cancellationToken).ConfigureAwait(false);
        return DecodeTap(document, representation, cancellationToken);
    }

    private static SequentialDecodeResult DecodeTap(MediaImageDocument document, SequentialMediaImageRepresentation representation, CancellationToken cancellationToken)
    {
        var clockRate = TryReadInt(document.Metadata, CommodoreTapConstants.ClockRateMetadataKey, out var storedClock) ? storedClock : CommodoreTapConstants.DefaultC64PalClockRate;
        var pulses = new List<Pulse>();
        foreach (var segment in (representation.Segments ?? []).OrderBy(segment => segment.Position))
        {
            cancellationToken.ThrowIfCancellationRequested();
            if (segment.Kind != SequentialSegmentKind.Pulse) continue;
            int cycles;
            if (!TryReadInt(segment.Metadata, CommodoreTapConstants.CycleCountMetadataKey, out cycles))
            {
                if (segment.Duration is not { } duration) continue;
                cycles = checked((int)Math.Round(duration.TotalSeconds * clockRate));
            }
            pulses.Add(new Pulse(cycles, segment.Position));
        }
        return CreateResult(representation, pulses, "tap-pulses");
    }

    private static async Task<SequentialDecodeResult> DecodeWaveAsync(MediaImageDocument document, SequentialMediaImageRepresentation representation, CancellationToken cancellationToken)
    {
        if (!PcmSampleFunctions.TryGetProfile(document.Metadata, out var channels, out var sampleRate, out var bitsPerSample, out var blockAlign))
            return new SequentialDecodeResult(CommodoreTapConstants.DecoderId, 0, [], representation.Segments ?? [], ["The WAV PCM profile is incomplete or incompatible."]);

        var pulses = new List<Pulse>();
        foreach (var segment in (representation.Segments ?? []).Where(segment => segment.Kind == SequentialSegmentKind.Samples && segment.ChannelNumber == 0).OrderBy(segment => segment.Position))
        {
            cancellationToken.ThrowIfCancellationRequested();
            if (segment.DataRange is not { Source: not null, Length: <= int.MaxValue } range) continue;
            var pcm = new byte[checked((int)range.Length)];
            await range.Source.ReadExactlyAsync(range.SourceOffset, pcm, cancellationToken).ConfigureAwait(false);
            var samples = PcmSampleFunctions.ExtractChannel(pcm, channels, bitsPerSample, blockAlign, 0);
            AddWavePulses(samples, sampleRate, segment.Position, pulses);
        }
        return CreateResult(representation, pulses, "wav-pulses");
    }

    private static SequentialDecodeResult CreateResult(SequentialMediaImageRepresentation representation, IReadOnlyList<Pulse> pulses, string sourceKind)
    {
        var blocks = new List<SequentialDecodedBlock>();
        var consumed = new HashSet<long>();
        for (var scan = 0; scan + 1 < pulses.Count;)
        {
            if (!IsPulse(pulses[scan].Cycles, CommodoreTapConstants.LongPulseCycles)
                || !IsPulse(pulses[scan + 1].Cycles, CommodoreTapConstants.MediumPulseCycles))
            {
                scan++;
                continue;
            }

            var blockStart = scan;
            var bytes = new List<byte>();
            var parityValid = true;
            while (TryDecodeByte(pulses, ref scan, out var value, out var validParity))
            {
                bytes.Add(value);
                parityValid &= validParity;
            }
            if (bytes.Count == 0)
            {
                scan = blockStart + 1;
                continue;
            }

            var sourcePositions = pulses.Skip(blockStart).Take(scan - blockStart).Select(pulse => pulse.SourcePosition).Distinct().ToArray();
            foreach (var position in sourcePositions) consumed.Add(position);
            blocks.Add(new SequentialDecodedBlock(
                blocks.Count,
                bytes.ToArray(),
                sourcePositions,
                parityValid,
                new Dictionary<string, string>(StringComparer.Ordinal)
                {
                    [CommodoreTapConstants.SourceKindMetadataKey] = sourceKind,
                    [CommodoreTapConstants.ParityValidMetadataKey] = parityValid.ToString(CultureInfo.InvariantCulture),
                    [CommodoreTapConstants.ChecksumPresentMetadataKey] = bool.FalseString
                }));
        }

        var undecoded = (representation.Segments ?? []).Where(segment => !consumed.Contains(segment.Position)).ToArray();
        var confidence = blocks.Count == 0 ? 0 : blocks.Count(block => block.IntegrityValid == true) / (double)blocks.Count;
        return new SequentialDecodeResult(CommodoreTapConstants.DecoderId, confidence, blocks, undecoded, blocks.Count == 0 ? ["No standard Commodore ROM byte frame was recognized."] : []);
    }

    private static bool TryDecodeByte(IReadOnlyList<Pulse> pulses, ref int offset, out byte value, out bool parityValid)
    {
        value = 0;
        parityValid = false;
        var required = 2 + (CommodoreTapConstants.DataBitsPerByte + CommodoreTapConstants.ParityBitsPerByte) * CommodoreTapConstants.PulsesPerBit;
        if (offset + required > pulses.Count
            || !IsPulse(pulses[offset].Cycles, CommodoreTapConstants.LongPulseCycles)
            || !IsPulse(pulses[offset + 1].Cycles, CommodoreTapConstants.MediumPulseCycles))
            return false;

        var cursor = offset + 2;
        var ones = 0;
        for (var bit = 0; bit < CommodoreTapConstants.DataBitsPerByte; bit++)
        {
            if (!TryDecodeBit(pulses[cursor].Cycles, pulses[cursor + 1].Cycles, out var set)) return false;
            if (set)
            {
                value |= (byte)(1 << bit);
                ones++;
            }
            cursor += CommodoreTapConstants.PulsesPerBit;
        }
        if (!TryDecodeBit(pulses[cursor].Cycles, pulses[cursor + 1].Cycles, out var parity)) return false;
        parityValid = ((ones + (parity ? 1 : 0)) & 1) == 1;
        offset = cursor + CommodoreTapConstants.PulsesPerBit;
        return true;
    }

    private static bool TryDecodeBit(int firstCycles, int secondCycles, out bool value)
    {
        value = false;
        if (IsPulse(firstCycles, CommodoreTapConstants.ShortPulseCycles)
            && IsPulse(secondCycles, CommodoreTapConstants.MediumPulseCycles))
            return true;
        if (IsPulse(firstCycles, CommodoreTapConstants.MediumPulseCycles)
            && IsPulse(secondCycles, CommodoreTapConstants.ShortPulseCycles))
        {
            value = true;
            return true;
        }
        return false;
    }

    private static void AddWavePulses(IReadOnlyList<int> samples, int sampleRate, long sourcePosition, List<Pulse> pulses)
    {
        if (samples.Count == 0) return;
        var previousSign = samples[0] >= 0;
        var previousCrossing = 0;
        for (var index = 1; index < samples.Count; index++)
        {
            var sign = samples[index] >= 0;
            if (sign == previousSign) continue;
            var cycles = checked((int)Math.Round((index - previousCrossing) * (double)CommodoreTapConstants.DefaultC64PalClockRate / sampleRate));
            if (cycles > 0) pulses.Add(new Pulse(cycles, sourcePosition));
            previousCrossing = index;
            previousSign = sign;
        }
    }

    private static bool IsPulse(int actual, int expected) => Math.Abs(actual - expected) <= expected * CommodoreTapConstants.PulseToleranceRatio;

    private static bool TryReadInt(IReadOnlyDictionary<string, string> metadata, string key, out int value)
    {
        value = 0;
        return metadata.TryGetValue(key, out var text) && int.TryParse(text, NumberStyles.None, CultureInfo.InvariantCulture, out value) && value > 0;
    }

    private readonly record struct Pulse(int Cycles, long SourcePosition);
}

using System.Buffers.Binary;
using System.Collections.Frozen;
using System.Globalization;
using GWGUI.MediaEngine.Enums;
using GWGUI.MediaEngine.Constants;
using GWGUI.MediaEngine.Contracts;

using GWGUI.MediaEngine.Interfaces;
using GWGUI.MediaEngine.Interfaces.Writing;
using GWGUI.MediaEngine.Images.Models.Sequential;

namespace GWGUI.MediaEngine.Images.Formats.Tape.CommodoreTap;

/// <summary>Writes pulse durations that are exactly representable by the selected Commodore TAP version.</summary>
public sealed class CommodoreTapWriter : IMediaImageWriter
{
    private static readonly IReadOnlySet<string> SupportedFormatIds = new[] { TapeImageFormatIds.CommodoreTap }.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
    private static readonly IReadOnlySet<MediaRepresentationKind> SupportedRepresentationKinds = new[] { MediaRepresentationKind.Sequential }.ToFrozenSet();
    private readonly IAtomicImageFileWriter files;

    public CommodoreTapWriter(IAtomicImageFileWriter? files = null) => this.files = files ?? new AtomicImageFileWriter();

    public string Id => MediaImageWriterIds.TapeCommodoreTap;
    public IReadOnlySet<string> FormatIds => SupportedFormatIds;
    public IReadOnlySet<MediaRepresentationKind> RepresentationKinds => SupportedRepresentationKinds;
    public IReadOnlySet<string> ProducedFileExtensions => CommodoreTapFormat.Extensions;
    public bool ProducesMultipleFiles => false;

    public bool CanWrite(MediaImageDocument document, string targetFormatId, string targetExtension) =>
        SupportedFormatIds.Contains(targetFormatId)
        && CommodoreTapFormat.Extensions.Contains(targetExtension)
        && document.MediaKind == MediaKind.Tape
        && TryGetProfile(document.Metadata, out var profile)
        && TryEncodeRecords(document, profile.Version, out _);

    public async Task<IReadOnlyList<string>> WriteAsync(MediaImageDocument document, string outputPath, string targetFormatId, CancellationToken cancellationToken = default)
    {
        var extension = Path.GetExtension(outputPath).ToLowerInvariant();
        if (!SupportedFormatIds.Contains(targetFormatId)
            || !CommodoreTapFormat.Extensions.Contains(extension)
            || document.MediaKind != MediaKind.Tape
            || !TryGetProfile(document.Metadata, out var profile)
            || !TryEncodeRecords(document, profile.Version, out var records))
            throw new InvalidDataException("The sequential document contains pulses that cannot be represented by the selected Commodore TAP profile.");

        var dataLength = records.Sum(record => (long)record.Length);
        if (dataLength > uint.MaxValue) throw new NotSupportedException("The Commodore TAP pulse stream exceeds its 32-bit data length.");
        await files.WriteAsync(
            outputPath,
            async (output, token) =>
            {
                var header = new byte[CommodoreTapConstants.HeaderSize];
                System.Text.Encoding.ASCII.GetBytes(profile.Signature, header.AsSpan(CommodoreTapConstants.SignatureOffset));
                header[CommodoreTapConstants.VersionOffset] = profile.Version;
                header[CommodoreTapConstants.PlatformOffset] = profile.Platform;
                header[CommodoreTapConstants.VideoStandardOffset] = profile.VideoStandard;
                BinaryPrimitives.WriteUInt32LittleEndian(header.AsSpan(CommodoreTapConstants.DataLengthOffset, CommodoreTapConstants.DataLengthSize), checked((uint)dataLength));
                await output.WriteAsync(header, token).ConfigureAwait(false);
                foreach (var record in records) await output.WriteAsync(record, token).ConfigureAwait(false);
            },
            cancellationToken).ConfigureAwait(false);
        return [outputPath];
    }

    private static bool TryGetProfile(IReadOnlyDictionary<string, string> metadata, out TapProfile profile)
    {
        profile = default;
        if (!metadata.TryGetValue(CommodoreTapConstants.SignatureMetadataKey, out var signature)
            || !CommodoreTapFormat.Signatures.Contains(signature)
            || !TryReadByte(metadata, CommodoreTapConstants.VersionMetadataKey, out var version)
            || !CommodoreTapFormat.Versions.Contains(version)
            || !TryReadByte(metadata, CommodoreTapConstants.PlatformMetadataKey, out var platform)
            || !TryReadByte(metadata, CommodoreTapConstants.VideoStandardMetadataKey, out var videoStandard)
            || !CommodoreTapConstants.TimerClockRates.ContainsKey((platform, videoStandard)))
            return false;
        profile = new TapProfile(signature, version, platform, videoStandard);
        return true;
    }

    private static bool TryEncodeRecords(MediaImageDocument document, byte version, out IReadOnlyList<byte[]> records)
    {
        records = [];
        if (document.Representation is not SequentialMediaImageRepresentation { Segments: { Count: > 0 } segments }) return false;
        var encoded = new List<byte[]>(segments.Count);
        foreach (var segment in segments.OrderBy(segment => segment.Position))
        {
            if (segment.Kind != SequentialSegmentKind.Pulse
                || !segment.Metadata.TryGetValue(CommodoreTapConstants.CycleCountMetadataKey, out var cycleText)
                || !int.TryParse(cycleText, NumberStyles.None, CultureInfo.InvariantCulture, out var cycles)
                || cycles <= 0)
                return false;
            if (cycles % CommodoreTapConstants.ShortPulseCycleMultiplier == 0
                && cycles / CommodoreTapConstants.ShortPulseCycleMultiplier is >= 1 and <= byte.MaxValue)
            {
                encoded.Add([(byte)(cycles / CommodoreTapConstants.ShortPulseCycleMultiplier)]);
                continue;
            }
            if (version == CommodoreTapConstants.OriginalVersion || cycles > 0x00ff_ffff) return false;
            encoded.Add([0, (byte)cycles, (byte)(cycles >> 8), (byte)(cycles >> 16)]);
        }
        records = encoded;
        return true;
    }

    private static bool TryReadByte(IReadOnlyDictionary<string, string> metadata, string key, out byte value)
    {
        value = 0;
        return metadata.TryGetValue(key, out var text) && byte.TryParse(text, NumberStyles.None, CultureInfo.InvariantCulture, out value);
    }

    private readonly record struct TapProfile(string Signature, byte Version, byte Platform, byte VideoStandard);
}

using System.Buffers.Binary;
using System.Collections.Frozen;
using System.IO;
using GWGUI.MediaEngine.Constants;
using GWGUI.MediaEngine.Contracts;
using GWGUI.MediaEngine.Enums;
using GWGUI.MediaEngine.Images.Models.Blocks;
using GWGUI.MediaEngine.Images.Writing;
using GWGUI.MediaEngine.Interfaces;
using GWGUI.MediaEngine.Interfaces.Writing;

namespace GWGUI.MediaEngine.Images.Formats.Cartridge.AmstradCpr;

/// <summary>Writes mapped 16 KiB cartridge pages as ordered RIFF AMS! cbNN chunks.</summary>
public sealed class AmstradCprWriter : IMediaImageWriter
{
    private const int BankLength = 16 * 1024;
    private const int MaximumBankCount = 32;
    private static readonly IReadOnlySet<string> SupportedFormatIds = new[] { DiskImageFormatIds.AmstradCpr }.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
    private static readonly IReadOnlySet<string> SupportedExtensions = new[] { DiskImageFileExtensions.Cpr }.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
    private static readonly IReadOnlySet<MediaRepresentationKind> SupportedRepresentations = new[] { MediaRepresentationKind.Blocks }.ToFrozenSet();
    private readonly IAtomicImageFileWriter files;

    public AmstradCprWriter(IAtomicImageFileWriter? files = null) => this.files = files ?? new AtomicImageFileWriter();

    public string Id => MediaImageWriterIds.AmstradCpr;
    public IReadOnlySet<string> FormatIds => SupportedFormatIds;
    public IReadOnlySet<MediaRepresentationKind> RepresentationKinds => SupportedRepresentations;
    public IReadOnlySet<string> ProducedFileExtensions => SupportedExtensions;
    public bool ProducesMultipleFiles => false;

    public bool CanWrite(MediaImageDocument document, string targetFormatId, string targetExtension) => SupportedFormatIds.Contains(targetFormatId) && SupportedExtensions.Contains(targetExtension) && TryGetBanks(document, out _);

    public async Task<IReadOnlyList<string>> WriteAsync(MediaImageDocument document, string outputPath, string targetFormatId, CancellationToken cancellationToken = default)
    {
        if (!CanWrite(document, targetFormatId, Path.GetExtension(outputPath).ToLowerInvariant())
            || !TryGetBanks(document, out var banks))
            throw new InvalidDataException("The block document cannot be written as a complete CPR cartridge.");
        await files.WriteAsync(outputPath, (output, token) => WriteCprAsync(output, banks, token), cancellationToken).ConfigureAwait(false);
        return [outputPath];
    }

    private static async Task WriteCprAsync(Stream output, IReadOnlyList<Bank> banks, CancellationToken cancellationToken)
    {
        var riffSize = checked(4 + banks.Sum(bank => 8 + bank.Length + (bank.Length & 1)));
        var header = new byte[12];
        System.Text.Encoding.ASCII.GetBytes("RIFF", header);
        BinaryPrimitives.WriteUInt32LittleEndian(header.AsSpan(4), checked((uint)riffSize));
        System.Text.Encoding.ASCII.GetBytes("AMS!", header.AsSpan(8));
        await output.WriteAsync(header, cancellationToken).ConfigureAwait(false);
        var buffer = new byte[64 * 1024];
        foreach (var bank in banks)
        {
            var chunkHeader = new byte[8];
            System.Text.Encoding.ASCII.GetBytes($"cb{bank.Number:D2}", chunkHeader);
            BinaryPrimitives.WriteUInt32LittleEndian(chunkHeader.AsSpan(4), checked((uint)bank.Length));
            await output.WriteAsync(chunkHeader, cancellationToken).ConfigureAwait(false);
            var completed = 0L;
            while (completed < bank.Length)
            {
                var count = (int)Math.Min(buffer.Length, bank.Length - completed);
                await bank.Range.Source!.ReadExactlyAsync(bank.Range.SourceOffset + completed, buffer.AsMemory(0, count), cancellationToken).ConfigureAwait(false);
                await output.WriteAsync(buffer.AsMemory(0, count), cancellationToken).ConfigureAwait(false);
                completed += count;
            }
            if ((bank.Length & 1) != 0) await output.WriteAsync(new byte[1], cancellationToken).ConfigureAwait(false);
        }
    }

    private static bool TryGetBanks(MediaImageDocument document, out IReadOnlyList<Bank> banks)
    {
        banks = [];
        if (document.Representation is not BlockMediaImageRepresentation blocks
            || blocks.Capacity <= 0
            || blocks.Capacity > MaximumBankCount * (long)BankLength)
            return false;
        var selected = new List<Bank>();
        foreach (var range in blocks.Ranges)
        {
            if (range.Kind != MediaDataRangeKind.Stored || range.Source is null
                || range.Address % BankLength != 0 || range.Length is <= 0 or > BankLength)
                return false;
            var number = checked((int)(range.Address / BankLength));
            var length = document.Metadata.TryGetValue($"bank.{number}.length", out var text) && int.TryParse(text, System.Globalization.NumberStyles.None, System.Globalization.CultureInfo.InvariantCulture, out var storedLength) ? storedLength : checked((int)range.Length);
            if (length <= 0 || length > range.Length) return false;
            selected.Add(new Bank(number, length, range));
        }
        if (selected.Count == 0 || selected.Select(bank => bank.Number).Distinct().Count() != selected.Count) return false;
        banks = selected.OrderBy(bank => bank.Number).ToArray();
        return true;
    }

    private sealed record Bank(int Number, int Length, MediaDataRange Range);
}

