using System.Globalization;
using GWGUI.MediaEngine.Images.Conversion.Flux;
using GWGUI.MediaEngine.Images.Formats.Floppy.Scp;
using GWGUI.MediaEngine.Images.Models.Flux;

namespace GWGUI.MediaEngine.Images.Formats.Floppy.Hfe;

/// <summary>Builds an HFE v1 container model from the common protected-track representation.</summary>
internal static class ProtectedTrackHfeImageAdapter
{
    public static HfeImage Create(ProtectedTrackImage image, IReadOnlyDictionary<string, string> metadata)
    {
        ArgumentNullException.ThrowIfNull(image);
        ArgumentNullException.ThrowIfNull(metadata);
        var tracks = image.Tracks.Select(ToHfeTrack).ToArray();
        ValidateTrackLayout(tracks);
        var bitRates = tracks.Select(track => CalculateBitRate(track.BitCellTicks)).Distinct().ToArray();
        if (bitRates.Length != 1)
            throw new NotSupportedException("HFE v1 requires one bit rate for every track.");
        var bitRate = ReadUInt16(metadata, HfeMetadataKeys.BitRate) ?? bitRates[0];
        if (bitRate != bitRates[0])
            throw new InvalidDataException("The HFE metadata bit rate does not match the represented track timing.");
        return new HfeImage(ReadByte(metadata, HfeMetadataKeys.Revision) ?? HfeFormat.Revision, tracks.Max(track => track.Cylinder) + 1, tracks.Max(track => track.Head) + 1, ResolveEncoding(metadata), bitRate, tracks);
    }

    private static HfeTrack ToHfeTrack(ProtectedTrack track)
    {
        if (track.Bits is { Count: > 0 })
            return new HfeTrack(track.Cylinder, track.Head, track.Bits, ResolveBitCellTicks(track));
        if (track.Revolutions.Count != 1)
            throw new NotSupportedException("HFE v1 cannot preserve multiple separate flux revolutions.");

        var revolution = track.Revolutions[0];
        if (revolution.ResolutionNanoseconds % HfeFormat.TickNanoseconds != 0)
            throw new NotSupportedException("The flux timing resolution cannot be expressed in HFE ticks.");
        var scale = checked((uint)(revolution.ResolutionNanoseconds / HfeFormat.TickNanoseconds));
        var values = revolution.Flux.FluxIntervals.Append(revolution.Flux.IndexTimeTicks).Select(value => checked(value * scale));
        var bitCellTicks = FluxBitCellConverter.GreatestCommonDivisor(values);
        if (bitCellTicks == 0) throw new InvalidDataException("The flux track does not contain representable timing.");
        var intervals = revolution.Flux.FluxIntervals.Select(value => checked(value * scale)).ToArray();
        var indexTime = checked(revolution.Flux.IndexTimeTicks * scale);
        var bits = FluxBitCellConverter.ToBits(intervals, indexTime, bitCellTicks);
        return new HfeTrack(track.Cylinder, track.Head, bits, bitCellTicks);
    }

    private static uint ResolveBitCellTicks(ProtectedTrack track)
    {
        if (track.Timing.Count != 1 ||
            track.Timing[0].BitOffset != 0 ||
            track.Timing[0].BitLength != track.Bits!.Count)
            throw new NotSupportedException("HFE v1 requires one uniform timing segment for each track.");
        var nanoseconds = track.Timing[0].BitCellNanoseconds;
        var ticks = nanoseconds / HfeFormat.TickNanoseconds;
        if (ticks < 1 || ticks > uint.MaxValue || ticks != Math.Truncate(ticks))
            throw new NotSupportedException("The track bit-cell timing cannot be expressed in HFE ticks.");
        return checked((uint)ticks);
    }

    private static void ValidateTrackLayout(IReadOnlyList<HfeTrack> tracks)
    {
        if (tracks.Count == 0) throw new InvalidDataException("HFE requires at least one track.");
        if (tracks.Any(track => track.Head >= HfeFormat.MaximumHeadCount))
            throw new NotSupportedException("HFE v1 supports at most two heads.");
        if (tracks.Any(track => track.Bits.Count % HfeFormat.BitsPerByte != 0))
            throw new NotSupportedException("HFE v1 would require padding at the end of a flux track.");
        for (var cylinder = 0; cylinder <= tracks.Max(track => track.Cylinder); cylinder++)
        {
            var sides = tracks.Where(track => track.Cylinder == cylinder).ToArray();
            if (sides.Length == 0) throw new NotSupportedException($"HFE v1 requires cylinder '{cylinder}'.");
            if (sides.Select(track => track.Bits.Count).Distinct().Count() != 1)
                throw new NotSupportedException("HFE v1 would require different padding between heads.");
        }
    }

    private static byte ResolveEncoding(IReadOnlyDictionary<string, string> metadata)
    {
        var hfeEncoding = ReadByte(metadata, HfeMetadataKeys.Encoding);
        if (hfeEncoding.HasValue) return hfeEncoding.Value;
        var scpDiskType = ReadByte(metadata, ScpMetadataKeys.DiskType);
        if (scpDiskType.HasValue) return ScpHfeEncodingResolver.Resolve(scpDiskType.Value);
        throw new NotSupportedException("The flux document does not declare an HFE encoding or an SCP disk type.");
    }

    private static ushort CalculateBitRate(uint bitCellTicks)
    {
        if (bitCellTicks == 0) throw new InvalidDataException("The HFE bit-cell duration cannot be zero.");
        var value = HfeFormat.NanosecondsPerSecond / (HfeFormat.BitsPerDataBit * HfeFormat.TickNanoseconds * 1000L * bitCellTicks);
        if (value is < 1 or > ushort.MaxValue)
            throw new NotSupportedException($"The calculated HFE bit rate '{value}' is invalid.");
        return checked((ushort)value);
    }

    private static byte? ReadByte(IReadOnlyDictionary<string, string> metadata, string key) => metadata.TryGetValue(key, out var value) && byte.TryParse(value, NumberStyles.None, CultureInfo.InvariantCulture, out var parsed) ? parsed : null;

    private static ushort? ReadUInt16(IReadOnlyDictionary<string, string> metadata, string key) => metadata.TryGetValue(key, out var value) && ushort.TryParse(value, NumberStyles.None, CultureInfo.InvariantCulture, out var parsed) ? parsed : null;
}

using System.Globalization;
using GWGUI.MediaEngine.Images.Models.Flux;

namespace GWGUI.MediaEngine.Images.Formats.Floppy.Scp;

/// <summary>Builds an SCP container model from the common protected-track representation.</summary>
internal static class ProtectedTrackScpImageAdapter
{
    public static ScpImage Create(ProtectedTrackImage image, IReadOnlyDictionary<string, string> metadata)
    {
        ArgumentNullException.ThrowIfNull(image);
        ArgumentNullException.ThrowIfNull(metadata);
        if (image.Tracks.Count == 0) throw new InvalidDataException("SCP requires at least one flux track.");

        var revolutionCount = image.Tracks.Min(track => track.Revolutions.Count);
        if (revolutionCount == 0 || revolutionCount > byte.MaxValue)
            throw new NotSupportedException("SCP requires at least one revolution on every track.");
        var resolutions = image.Tracks.SelectMany(track => track.Revolutions).Select(revolution => revolution.ResolutionNanoseconds).Distinct().ToArray();
        int? commonResolution = resolutions.Length == 1 ? resolutions[0] : null;
        var resolution = ResolveResolution(metadata, commonResolution);
        var resolutionNanoseconds = ScpFormatConstants.ResolutionStepNanoseconds * (resolution + ScpFormatConstants.ResolutionIndexOffset);

        var tracks = image.Tracks
            .Select(track => new ScpTrack(
                ScpFormatConstants.ToTrackNumber(track.Cylinder, track.Head),
                track.Cylinder,
                track.Head,
                track.Revolutions.Take(revolutionCount).Select(revolution => ConvertRevolution(revolution, resolutionNanoseconds)).ToArray()))
            .OrderBy(track => track.TrackNumber)
            .ToArray();
        var flags = ReadByte(metadata, ScpMetadataKeys.Flags) is { } rawFlags ? (ScpFlags)rawFlags : ScpFlags.IndexAligned | ScpFlags.ThirdPartyCreator | (image.WriteProtected ? ScpFlags.None : ScpFlags.Writable);
        flags &= ~(ScpFlags.Footer | ScpFlags.Extended);
        var header = new ScpHeader(
            ReadByte(metadata, ScpMetadataKeys.Version) ?? ScpWriterDefaults.Version,
            ReadByte(metadata, ScpMetadataKeys.DiskType) ?? (byte)ScpDiskType.Other720,
            checked((byte)revolutionCount),
            tracks.Min(track => track.TrackNumber),
            tracks.Max(track => track.TrackNumber),
            flags,
            (ScpBitCellEncoding)(ReadByte(metadata, ScpMetadataKeys.BitCellEncoding) ??
                                 (byte)ScpBitCellEncoding.Default16Bit),
            ResolveHeads(tracks),
            resolution,
            ScpFormatConstants.MissingChecksum);
        return new ScpImage(header, tracks, true, ScpWriterDefaults.InitialFileSize);
    }

    private static byte ResolveResolution(IReadOnlyDictionary<string, string> metadata, int? resolutionNanoseconds)
    {
        var stored = ReadByte(metadata, ScpMetadataKeys.Resolution);
        if (stored.HasValue) return stored.Value;
        if (resolutionNanoseconds is null ||
            resolutionNanoseconds.Value % ScpFormatConstants.ResolutionStepNanoseconds != 0)
            return ScpFormatConstants.InternalCaptureResolution;
        var index = resolutionNanoseconds.Value / ScpFormatConstants.ResolutionStepNanoseconds - ScpFormatConstants.ResolutionIndexOffset;
        return index is < byte.MinValue or > byte.MaxValue ? ScpFormatConstants.InternalCaptureResolution : checked((byte)index);
    }

    private static ScpRevolution ConvertRevolution(TrackFluxRevolution source, int targetResolutionNanoseconds)
    {
        var intervals = source.Flux.FluxIntervals.Select(interval => ConvertTicks(interval, source.ResolutionNanoseconds, targetResolutionNanoseconds)).ToArray();
        var indexTime = ConvertTicks(source.Flux.IndexTimeTicks, source.ResolutionNanoseconds, targetResolutionNanoseconds);
        return new(new FluxRevolution(indexTime, intervals), checked((uint)intervals.Length));
    }

    private static uint ConvertTicks(uint ticks, int sourceResolution, int targetResolution)
    {
        var converted = ((ulong)ticks * checked((uint)sourceResolution) + (uint)(targetResolution / 2)) / checked((uint)targetResolution);
        if (converted == 0) return 1;
        if (converted > uint.MaxValue)
            throw new NotSupportedException("Flux timing exceeds the SCP range.");
        return checked((uint)converted);
    }

    private static ScpHeadSelection ResolveHeads(IReadOnlyList<ScpTrack> tracks)
    {
        var heads = tracks.Select(track => track.Head).Distinct().Order().ToArray();
        if (heads.SequenceEqual([0])) return ScpHeadSelection.Side0;
        if (heads.SequenceEqual([1])) return ScpHeadSelection.Side1;
        if (heads.SequenceEqual([0, 1])) return ScpHeadSelection.Both;
        throw new NotSupportedException("SCP supports only floppy heads zero and one.");
    }

    private static byte? ReadByte(IReadOnlyDictionary<string, string> metadata, string key) => metadata.TryGetValue(key, out var value) && byte.TryParse(value, NumberStyles.None, CultureInfo.InvariantCulture, out var parsed) ? parsed : null;
}

using GWGUI.MediaFileSystems.Functions;
using System.Buffers.Binary;
using System.Collections.Frozen;
using System.Globalization;
using GWGUI.MediaEngine.Enums;
using GWGUI.MediaEngine.Constants;
using GWGUI.MediaEngine.Contracts;

using GWGUI.MediaEngine.Interfaces;
using GWGUI.MediaEngine.Interfaces.Writing;
using GWGUI.MediaEngine.Images.Models.Sequential;

namespace GWGUI.MediaEngine.Images.Formats.Tape.CommodoreTap;

/// <summary>Writes pulse durations that are exactly representable by the selected Commodore TAP version.</summary>
public sealed class CommodoreTapWriter : IMediaImageWriter
{
    private static readonly IReadOnlySet<string> SupportedFormatIds = new[] { TapeImageFormatIds.CommodoreTap }.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
    private static readonly IReadOnlySet<MediaRepresentationKind> SupportedRepresentationKinds = new[] { MediaRepresentationKind.Sequential }.ToFrozenSet();
    private readonly IAtomicImageFileWriter files;

    public CommodoreTapWriter(IAtomicImageFileWriter? files = null) => this.files = files ?? new AtomicImageFileWriter();

    public string Id => MediaImageWriterIds.TapeCommodoreTap;
    public IReadOnlySet<string> FormatIds => SupportedFormatIds;
    public IReadOnlySet<MediaRepresentationKind> RepresentationKinds => SupportedRepresentationKinds;
    public IReadOnlySet<string> ProducedFileExtensions => CommodoreTapFormat.Extensions;
    public bool ProducesMultipleFiles => false;

    public bool CanWrite(MediaImageDocument document, string targetFormatId, string targetExtension) =>
        SupportedFormatIds.Contains(targetFormatId)
        && CommodoreTapFormat.Extensions.Contains(targetExtension)
        && document.MediaKind == MediaKind.Tape
        && TryGetProfile(document.Metadata, out var profile)
        && TryEncodeRecords(document, profile.Version, out _);

    public async Task<IReadOnlyList<string>> WriteAsync(MediaImageDocument document, string outputPath, string targetFormatId, CancellationToken cancellationToken = default)
    {
        var extension = Path.GetExtension(outputPath).ToLowerInvariant();
        if (!SupportedFormatIds.Contains(targetFormatId)
            || !CommodoreTapFormat.Extensions.Contains(extension)
            || document.MediaKind != MediaKind.Tape
            || !TryGetProfile(document.Metadata, out var profile)
            || !TryEncodeRecords(document, profile.Version, out var records))
            throw new InvalidDataException("The sequential document contains pulses that cannot be represented by the selected Commodore TAP profile.");

        var dataLength = records.Sum(record => (long)record.Length);
        if (dataLength > uint.MaxValue) throw new NotSupportedException("The Commodore TAP pulse stream exceeds its 32-bit data length.");
        await files.WriteAsync(
            outputPath,
            async (output, token) =>
            {
                var header = new byte[CommodoreTapConstants.HeaderSize];
                System.Text.Encoding.ASCII.GetBytes(profile.Signature, header.AsSpan(CommodoreTapConstants.SignatureOffset));
                header[CommodoreTapConstants.VersionOffset] = profile.Version;
                header[CommodoreTapConstants.PlatformOffset] = profile.Platform;
                header[CommodoreTapConstants.VideoStandardOffset] = profile.VideoStandard;
                BinaryPrimitives.WriteUInt32LittleEndian(header.AsSpan(CommodoreTapConstants.DataLengthOffset, CommodoreTapConstants.DataLengthSize), checked((uint)dataLength));
                await output.WriteAsync(header, token).ConfigureAwait(false);
                foreach (var record in records) await output.WriteAsync(record, token).ConfigureAwait(false);
            },
            cancellationToken).ConfigureAwait(false);
        return [outputPath];
    }

    private static bool TryGetProfile(IReadOnlyDictionary<string, string> metadata, out TapProfile profile)
    {
        profile = default;
        if (!metadata.TryGetValue(CommodoreTapConstants.SignatureMetadataKey, out var signature)
            || !CommodoreTapFormat.Signatures.Contains(signature)
            || !TryReadByte(metadata, CommodoreTapConstants.VersionMetadataKey, out var version)
            || !CommodoreTapFormat.Versions.Contains(version)
            || !TryReadByte(metadata, CommodoreTapConstants.PlatformMetadataKey, out var platform)
            || !TryReadByte(metadata, CommodoreTapConstants.VideoStandardMetadataKey, out var videoStandard)
            || !CommodoreTapConstants.TimerClockRates.ContainsKey((platform, videoStandard)))
            return false;
        profile = new TapProfile(signature, version, platform, videoStandard);
        return true;
    }

    private static bool TryEncodeRecords(MediaImageDocument document, byte version, out IReadOnlyList<byte[]> records)
    {
        records = [];
        if (document.Representation is not SequentialMediaImageRepresentation { Segments: { Count: > 0 } segments }) return false;
        var encoded = new List<byte[]>(segments.Count);
        foreach (var segment in segments.OrderBy(segment => segment.Position))
        {
            if (segment.Kind != SequentialSegmentKind.Pulse
                || !MediaMetadataFunctions.TryReadInt(segment.Metadata, CommodoreTapConstants.CycleCountMetadataKey, out var cycles)
                || cycles <= 0)
                return false;
            if (cycles % CommodoreTapConstants.ShortPulseCycleMultiplier == 0
                && cycles / CommodoreTapConstants.ShortPulseCycleMultiplier is >= 1 and <= byte.MaxValue)
            {
                encoded.Add([(byte)(cycles / CommodoreTapConstants.ShortPulseCycleMultiplier)]);
                continue;
            }
            if (version == CommodoreTapConstants.OriginalVersion || cycles > 0x00ff_ffff) return false;
            encoded.Add([0, (byte)cycles, (byte)(cycles >> 8), (byte)(cycles >> 16)]);
        }
        records = encoded;
        return true;
    }

    private static bool TryReadByte(IReadOnlyDictionary<string, string> metadata, string key, out byte value)
    {
        value = 0;
        return metadata.TryGetValue(key, out var text) && byte.TryParse(text, NumberStyles.None, CultureInfo.InvariantCulture, out value);
    }

    private readonly record struct TapProfile(string Signature, byte Version, byte Platform, byte VideoStandard);
}

