/// <summary>Writes explicit interleaved integer PCM segments without resampling or mixing channels.</summary>
public sealed class WavTapeWriter : IMediaImageWriter
{
    private static readonly IReadOnlySet<string> SupportedFormatIds = new[] { TapeImageFormatIds.Wav }.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
    private static readonly IReadOnlySet<MediaRepresentationKind> SupportedRepresentations = new[] { MediaRepresentationKind.Sequential }.ToFrozenSet();
    private readonly IAtomicImageFileWriter files;

    public WavTapeWriter(IAtomicImageFileWriter? files = null) => this.files = files ?? new AtomicImageFileWriter();

    public string Id => MediaImageWriterIds.TapeWav;
    public IReadOnlySet<string> FormatIds => SupportedFormatIds;
    public IReadOnlySet<MediaRepresentationKind> RepresentationKinds => SupportedRepresentations;
    public IReadOnlySet<string> ProducedFileExtensions => WavTapeFormat.Extensions;
    public bool ProducesMultipleFiles => false;

    public bool CanWrite(MediaImageDocument document, string targetFormatId, string targetExtension)
    {
        ArgumentNullException.ThrowIfNull(document);
        return SupportedFormatIds.Contains(targetFormatId) && WavTapeFormat.Extensions.Contains(targetExtension) && document.MediaKind == MediaKind.Tape && TryGetProfile(document, out _) && TryGetDataRanges(document, out _);
    }

    public async Task<IReadOnlyList<string>> WriteAsync(MediaImageDocument document, string outputPath, string targetFormatId, CancellationToken cancellationToken = default)
    {
        var extension = Path.GetExtension(outputPath).ToLowerInvariant();
        if (!CanWrite(document, targetFormatId, extension)
            || !TryGetProfile(document, out var profile)
            || !TryGetDataRanges(document, out var ranges))
            throw new InvalidDataException("The sequential document cannot be written as integer PCM WAV without resampling or data loss.");
        var dataLength = ranges.Sum(range => range.Length);
        if (dataLength > uint.MaxValue || dataLength + WavConstants.RiffHeaderSize + WavConstants.ChunkHeaderSize + WavConstants.PcmFormatChunkSize > uint.MaxValue + 8L)
            throw new NotSupportedException("The WAV output exceeds the RIFF 32-bit length limit.");
        await files.WriteAsync(outputPath, (output, token) => WriteWaveAsync(output, profile, ranges, dataLength, token), cancellationToken).ConfigureAwait(false);
        return [outputPath];
    }

    private static async Task WriteWaveAsync(Stream output, PcmProfile profile, IReadOnlyList<MediaDataRange> ranges, long dataLength, CancellationToken cancellationToken)
    {
        var header = new byte[WavConstants.RiffHeaderSize + WavConstants.ChunkHeaderSize + WavConstants.PcmFormatChunkSize + WavConstants.ChunkHeaderSize];
        WriteIdentifier(header, 0, WavConstants.RiffIdentifier);
        BinaryPrimitives.WriteUInt32LittleEndian(header.AsSpan(4), checked((uint)(header.Length - 8 + dataLength)));
        WriteIdentifier(header, 8, WavConstants.WaveIdentifier);
        WriteIdentifier(header, 12, WavConstants.FormatChunkIdentifier);
        BinaryPrimitives.WriteUInt32LittleEndian(header.AsSpan(16), WavConstants.PcmFormatChunkSize);
        BinaryPrimitives.WriteUInt16LittleEndian(header.AsSpan(20), WavConstants.PcmFormatTag);
        BinaryPrimitives.WriteUInt16LittleEndian(header.AsSpan(22), profile.Channels);
        BinaryPrimitives.WriteUInt32LittleEndian(header.AsSpan(24), profile.SampleRate);
        BinaryPrimitives.WriteUInt32LittleEndian(header.AsSpan(28), checked(profile.SampleRate * profile.BlockAlign));
        BinaryPrimitives.WriteUInt16LittleEndian(header.AsSpan(32), profile.BlockAlign);
        BinaryPrimitives.WriteUInt16LittleEndian(header.AsSpan(34), profile.BitsPerSample);
        WriteIdentifier(header, 36, WavConstants.DataChunkIdentifier);
        BinaryPrimitives.WriteUInt32LittleEndian(header.AsSpan(40), checked((uint)dataLength));
        await output.WriteAsync(header, cancellationToken).ConfigureAwait(false);
        var buffer = new byte[64 * 1024];
        foreach (var range in ranges)
        {
            var completed = 0L;
            while (completed < range.Length)
            {
                var count = (int)Math.Min(buffer.Length, range.Length - completed);
                await range.Source!.ReadExactlyAsync(range.SourceOffset + completed, buffer.AsMemory(0, count), cancellationToken).ConfigureAwait(false);
                await output.WriteAsync(buffer.AsMemory(0, count), cancellationToken).ConfigureAwait(false);
                completed += count;
            }
        }
        if ((dataLength & 1) != 0) await output.WriteAsync(new byte[1], cancellationToken).ConfigureAwait(false);
    }

    private static bool TryGetProfile(MediaImageDocument document, out PcmProfile profile)
    {
        profile = default;
        if (!TryReadUInt16(document.Metadata, "channels", out var channels)
            || !TryReadUInt32(document.Metadata, "sampleRate", out var sampleRate)
            || !TryReadUInt16(document.Metadata, "bitsPerSample", out var bitsPerSample)
            || !TryReadUInt16(document.Metadata, "blockAlign", out var blockAlign)
            || !WavTapeFormat.IsSupportedPcm(channels, checked((int)sampleRate), bitsPerSample)
            || blockAlign != channels * (bitsPerSample / 8))
            return false;
        profile = new PcmProfile(channels, sampleRate, bitsPerSample, blockAlign);
        return true;
    }

    private static bool TryGetDataRanges(MediaImageDocument document, out IReadOnlyList<MediaDataRange> ranges)
    {
        ranges = [];
        if (document.Representation is not SequentialMediaImageRepresentation { Segments: { } segments }
            || segments.Count == 0
            || segments.Any(segment => segment.Kind != SequentialSegmentKind.Samples || segment.DataRange?.Source is null))
            return false;
        var selected = segments.Where(segment => segment.ChannelNumber is null or 0).Select(segment => segment.DataRange!).ToArray();
        if (selected.Length == 0 || selected.Any(range => range.Kind != MediaDataRangeKind.Stored)) return false;
        ranges = selected;
        return true;
    }

    private static bool TryReadUInt16(IReadOnlyDictionary<string, string> values, string key, out ushort value)
    {
        value = 0;
        return values.TryGetValue(key, out var text) && ushort.TryParse(text, System.Globalization.NumberStyles.None, System.Globalization.CultureInfo.InvariantCulture, out value);
    }

    private static bool TryReadUInt32(IReadOnlyDictionary<string, string> values, string key, out uint value)
    {
        value = 0;
        return values.TryGetValue(key, out var text) && uint.TryParse(text, System.Globalization.NumberStyles.None, System.Globalization.CultureInfo.InvariantCulture, out value);
    }

    private static void WriteIdentifier(Span<byte> destination, int offset, string value) => System.Text.Encoding.ASCII.GetBytes(value, destination[offset..]);

    private readonly record struct PcmProfile(ushort Channels, uint SampleRate, ushort BitsPerSample, ushort BlockAlign);
}

using GWGUI.MediaEngine.Images.Reading.Blocks;
using System.Collections.Frozen;
using GWGUI.MediaEngine.Enums;
using GWGUI.MediaEngine.Constants;
using GWGUI.MediaEngine.Contracts;

using GWGUI.MediaEngine.Interfaces;
using GWGUI.MediaEngine.Interfaces.Writing;
using GWGUI.MediaEngine.Images.Models.Sequential;

namespace GWGUI.MediaEngine.Images.Formats.Tape.Tzx;

/// <summary>Writes retained TZX blocks verbatim after validating that every payload remains accessible.</summary>
public sealed class TzxWriter : IMediaImageWriter
{
    private static readonly IReadOnlySet<string> SupportedFormats = new[] { TapeImageFormatIds.Tzx }.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
    private static readonly IReadOnlySet<MediaRepresentationKind> SupportedRepresentations = new[] { MediaRepresentationKind.Sequential }.ToFrozenSet();
    private readonly IAtomicImageFileWriter files;

    public TzxWriter(IAtomicImageFileWriter? files = null) => this.files = files ?? new AtomicImageFileWriter();

    public string Id => MediaImageWriterIds.TapeTzx;
    public IReadOnlySet<string> FormatIds => SupportedFormats;
    public IReadOnlySet<MediaRepresentationKind> RepresentationKinds => SupportedRepresentations;
    public IReadOnlySet<string> ProducedFileExtensions => TzxFormat.Extensions;
    public bool ProducesMultipleFiles => false;

    public bool CanWrite(MediaImageDocument document, string targetFormatId, string targetExtension)
    {
        ArgumentNullException.ThrowIfNull(document);
        return SupportedFormats.Contains(targetFormatId) && TzxFormat.Extensions.Contains(targetExtension) && document.MediaKind == MediaKind.Tape && TryGetBlocks(document, out _);
    }

    public async Task<IReadOnlyList<string>> WriteAsync(MediaImageDocument document, string outputPath, string targetFormatId, CancellationToken cancellationToken = default)
    {
        var extension = Path.GetExtension(outputPath).ToLowerInvariant();
        if (!CanWrite(document, targetFormatId, extension) || !TryGetBlocks(document, out var blocks))
            throw new InvalidDataException("The sequential document cannot be written as TZX without losing block payloads.");
        var major = ReadVersion(document.Metadata, "majorVersion", TzxConstants.MajorVersion);
        var minor = ReadVersion(document.Metadata, "minorVersion", TzxConstants.MinorVersion);
        if (major != TzxConstants.MajorVersion || minor > TzxConstants.MinorVersion)
            throw new NotSupportedException($"TZX version {major}.{minor:D2} is outside the supported 1.20 profile.");

        await files.WriteAsync(outputPath, async (output, token) =>
        {
            var header = new byte[TzxConstants.HeaderSize];
            System.Text.Encoding.ASCII.GetBytes(TzxConstants.Signature, header);
            header[7] = TzxConstants.EndOfTextMarker;
            header[8] = major;
            header[9] = minor;
            await output.WriteAsync(header, token).ConfigureAwait(false);
            foreach (var block in blocks)
            {
                await output.WriteAsync(new[] { block.Id }, token).ConfigureAwait(false);
                if (block.Range is not null) await BlockMediaDataReader.CopyToAsync(block.Range, output, token).ConfigureAwait(false);
            }
        }, cancellationToken).ConfigureAwait(false);
        return [outputPath];
    }

    private static bool TryGetBlocks(MediaImageDocument document, out IReadOnlyList<TzxBlock> blocks)
    {
        blocks = [];
        if (document.Representation is not SequentialMediaImageRepresentation { Segments: { Count: > 0 } segments }) return false;
        var selected = new List<TzxBlock>(segments.Count);
        foreach (var segment in segments.OrderBy(segment => segment.Position))
        {
            if (!segment.Metadata.TryGetValue(TzxConstants.BlockIdMetadataKey, out var idText)
                || !byte.TryParse(idText, System.Globalization.NumberStyles.HexNumber, System.Globalization.CultureInfo.InvariantCulture, out var id))
                return false;
            if (segment.Length is null)
            {
                if (segment.DataRange is not null) return false;
                selected.Add(new TzxBlock(id, null));
                continue;
            }
            if (segment.DataRange is not { Kind: MediaDataRangeKind.Stored, Source: not null } range
                || range.Length != segment.Length)
                return false;
            selected.Add(new TzxBlock(id, range));
        }
        blocks = selected;
        return true;
    }

    private static byte ReadVersion(IReadOnlyDictionary<string, string> metadata, string key, byte defaultValue) =>
        metadata.TryGetValue(key, out var text) && byte.TryParse(text, System.Globalization.NumberStyles.None, System.Globalization.CultureInfo.InvariantCulture, out var value) ? value : defaultValue;

    private sealed record TzxBlock(byte Id, MediaDataRange? Range);
}

using System.Buffers.Binary;
using System.Collections.Frozen;
using GWGUI.MediaEngine.Constants;
using GWGUI.MediaEngine.Contracts;
using GWGUI.MediaEngine.Enums;
using GWGUI.MediaEngine.Interfaces.Encoding;
using GWGUI.MediaEngine.Images.Reading.Sources;
using GWGUI.MediaEngine.Images.Reading.Recognition;
using GWGUI.MediaEngine.Images.Models.Sequential;

namespace GWGUI.MediaEngine.Images.Writing.Encoding.Sequential.Tzx;

/// <summary>Encodes validated data blocks and explicit pulse or pause segments as retained TZX blocks.</summary>
public sealed class TzxSignalEncoder : ISequentialMediaEncoder
{
    private static readonly IReadOnlySet<string> SupportedFormats = new[] { TapeImageFormatIds.Tzx }.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
    private static readonly IReadOnlySet<string> SupportedMachines = new[] { DiskSystemIds.Spectrum, DiskSystemIds.Msx }.ToFrozenSet(StringComparer.OrdinalIgnoreCase);

    public string Id => TzxConstants.EncoderId;
    public IReadOnlySet<string> FormatIds => SupportedFormats;
    public IReadOnlySet<string> MachineIds => SupportedMachines;

    public bool CanEncode(SequentialEncodeRequest request)
    {
        ArgumentNullException.ThrowIfNull(request);
        return SupportedFormats.Contains(request.TargetFormatId) && SupportedMachines.Contains(request.MachineId) && request.Blocks.All(block => block.IntegrityValid == true && block.Data.Length <= ushort.MaxValue) && request.RetainedSegments.All(CanRetain);
    }

    public Task<SequentialMediaImageRepresentation> EncodeAsync(SequentialEncodeRequest request, CancellationToken cancellationToken = default)
    {
        if (!CanEncode(request))
            throw new InvalidDataException("TZX encoding requires validated blocks and retained TZX, pulse, or pause segments.");
        cancellationToken.ThrowIfCancellationRequested();

        var ordered = new List<OrderedItem>();
        ordered.AddRange(request.RetainedSegments.Select(segment => new OrderedItem(segment.Position, segment, null)));
        ordered.AddRange(request.Blocks.Select((block, index) => new OrderedItem(block.SourceSegmentPositions.Count == 0 ? long.MaxValue - request.Blocks.Count + index : block.SourceSegmentPositions.Min(), null, block)));

        var output = new List<SequentialMediaSegment>();
        foreach (var item in ordered.OrderBy(item => item.Position).ThenBy(item => item.Block is null ? 0 : 1))
        {
            cancellationToken.ThrowIfCancellationRequested();
            if (item.Block is not null)
            {
                output.Add(CreateBlock(output.Count, TzxConstants.StandardSpeedData, CreateStandardPayload(item.Block.Data.Span)));
                continue;
            }
            var source = item.Segment!;
            if (source.Metadata.ContainsKey(TzxConstants.BlockIdMetadataKey))
            {
                output.Add(source.AtPosition(output.Count));
                continue;
            }
            if (source.Kind == SequentialSegmentKind.Pulse)
            {
                var pulseTStates = ReadUInt16(source.Metadata, "pulseTStates");
                var pulseCount = ReadUInt16(source.Metadata, "pulseCount", 1);
                output.Add(CreateBlock(output.Count, TzxConstants.PureTone, CreatePureTonePayload(pulseTStates, pulseCount)));
                continue;
            }
            var milliseconds = checked((ushort)Math.Round(source.Duration!.Value.TotalMilliseconds));
            output.Add(CreateBlock(output.Count, TzxConstants.Pause, CreatePausePayload(milliseconds)));
        }

        var logicalLength = output.Sum(segment => segment.DataRange?.Length ?? 0);
        return Task.FromResult(new SequentialMediaImageRepresentation(logicalLength, segments: output));
    }

    private static bool CanRetain(SequentialMediaSegment segment)
    {
        if (segment.Metadata.ContainsKey(TzxConstants.BlockIdMetadataKey))
            return segment.Length is null && segment.DataRange is null || segment.DataRange is { Kind: MediaDataRangeKind.Stored, Source: not null } range && range.Length == segment.Length;
        if (segment.Kind == SequentialSegmentKind.Pulse)
            return TryReadUInt16(segment.Metadata, "pulseTStates", out _) && (!segment.Metadata.ContainsKey("pulseCount") || TryReadUInt16(segment.Metadata, "pulseCount", out _));
        return segment.Kind == SequentialSegmentKind.Silence && segment.Duration is { } duration && duration.TotalMilliseconds is >= 1 and <= ushort.MaxValue;
    }

    private static SequentialMediaSegment CreateBlock(long position, byte id, byte[] payload)
    {
        var source = new MemoryRandomAccessData(payload);
        return new SequentialMediaSegment(
            position,
            id switch
            {
                TzxConstants.Pause => SequentialSegmentKind.Silence,
                TzxConstants.PureTone or TzxConstants.PulseSequence => SequentialSegmentKind.Pulse,
                _ => SequentialSegmentKind.DataBlock
            },
            payload.Length,
            dataRange: new MediaDataRange(0, payload.Length, MediaDataRangeKind.Stored, source, 0),
            metadata: new Dictionary<string, string>(StringComparer.Ordinal)
            {
                [TzxConstants.BlockIdMetadataKey] = id.ToString("x2", System.Globalization.CultureInfo.InvariantCulture),
                ["payloadLength"] = payload.Length.ToString(System.Globalization.CultureInfo.InvariantCulture),
                ["known"] = bool.TrueString
            });
    }

    private static byte[] CreateStandardPayload(ReadOnlySpan<byte> data)
    {
        var payload = new byte[4 + data.Length];
        BinaryPrimitives.WriteUInt16LittleEndian(payload, TzxConstants.StandardPauseMilliseconds);
        BinaryPrimitives.WriteUInt16LittleEndian(payload.AsSpan(2), checked((ushort)data.Length));
        data.CopyTo(payload.AsSpan(4));
        return payload;
    }

    private static byte[] CreatePureTonePayload(ushort pulseTStates, ushort pulseCount)
    {
        var payload = new byte[4];
        BinaryPrimitives.WriteUInt16LittleEndian(payload, pulseTStates);
        BinaryPrimitives.WriteUInt16LittleEndian(payload.AsSpan(2), pulseCount);
        return payload;
    }

    private static byte[] CreatePausePayload(ushort milliseconds)
    {
        var payload = new byte[2];
        BinaryPrimitives.WriteUInt16LittleEndian(payload, milliseconds);
        return payload;
    }

    private static ushort ReadUInt16(IReadOnlyDictionary<string, string> metadata, string key, ushort defaultValue = 0) =>
        metadata.TryGetValue(key, out var text) && ushort.TryParse(text, System.Globalization.NumberStyles.None, System.Globalization.CultureInfo.InvariantCulture, out var value) ? value : defaultValue;

    private static bool TryReadUInt16(IReadOnlyDictionary<string, string> metadata, string key, out ushort value)
    {
        value = 0;
        return metadata.TryGetValue(key, out var text) && ushort.TryParse(text, System.Globalization.NumberStyles.None, System.Globalization.CultureInfo.InvariantCulture, out value) && value > 0;
    }

    private sealed record OrderedItem(long Position, SequentialMediaSegment? Segment, SequentialDecodedBlock? Block);
}

using System.Buffers.Binary;
using System.Collections.Frozen;
using System.Globalization;
using GWGUI.MediaEngine.Constants;
using GWGUI.MediaEngine.Contracts;
using GWGUI.MediaEngine.Enums;
using GWGUI.MediaEngine.Functions;
using GWGUI.MediaEngine.Interfaces.Encoding;
using GWGUI.MediaEngine.Images.Models.Sectors;
using GWGUI.MediaEngine.Images.Reading.Sources;
using GWGUI.MediaEngine.Images.Reading.Recognition;
using GWGUI.MediaEngine.Images.Models.Sequential;

namespace GWGUI.MediaEngine.Images.Writing.Encoding.Sequential.Acorn;

/// <summary>Rebuilds validated Acorn cassette blocks as UEF implicit data chunks or standard PCM FSK.</summary>
public sealed class AcornTapeEncoder : ISequentialMediaEncoder
{
    private static readonly IReadOnlySet<string> SupportedFormats = new[] { TapeImageFormatIds.Uef, TapeImageFormatIds.Wav }.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
    private static readonly IReadOnlySet<string> SupportedMachines = new[] { DiskSystemIds.AcornBbc }.ToFrozenSet(StringComparer.OrdinalIgnoreCase);

    public string Id => UefConstants.EncoderId;
    public IReadOnlySet<string> FormatIds => SupportedFormats;
    public IReadOnlySet<string> MachineIds => SupportedMachines;

    public bool CanEncode(SequentialEncodeRequest request)
    {
        ArgumentNullException.ThrowIfNull(request);
        return SupportedFormats.Contains(request.TargetFormatId)
            && SupportedMachines.Contains(request.MachineId)
            && request.Blocks.Count > 0
            && request.RetainedSegments.Count == 0
            && request.Blocks.All(block => block.IntegrityValid == true && TryBuildBlock(block, out _))
            && (!request.TargetFormatId.Equals(TapeImageFormatIds.Wav, StringComparison.OrdinalIgnoreCase)
                || PcmSampleFunctions.TryReadSampleRate(request.Parameters, out _));
    }

    public Task<SequentialMediaImageRepresentation> EncodeAsync(SequentialEncodeRequest request, CancellationToken cancellationToken = default)
    {
        if (!CanEncode(request))
            throw new InvalidDataException("Acorn tape encoding requires validated CFS blocks with complete cassette metadata.");
        cancellationToken.ThrowIfCancellationRequested();
        var encodedBlocks = request.Blocks.Select(block =>
        {
            TryBuildBlock(block, out var bytes);
            return bytes;
        }).ToArray();
        return Task.FromResult(request.TargetFormatId.Equals(TapeImageFormatIds.Wav, StringComparison.OrdinalIgnoreCase) ? EncodeWave(encodedBlocks, request.Parameters) : EncodeUef(encodedBlocks));
    }

    private static SequentialMediaImageRepresentation EncodeUef(IReadOnlyList<byte[]> blocks)
    {
        var segments = new List<SequentialMediaSegment>(blocks.Count);
        var elapsed = TimeSpan.Zero;
        for (var index = 0; index < blocks.Count; index++)
        {
            var bytes = blocks[index];
            var duration = TimeSpan.FromSeconds(bytes.Length * (1 + UefConstants.AcornDataBitsPerFrame + UefConstants.AcornStopBitsPerFrame) / (double)UefConstants.DefaultBaudRate);
            var source = new MemoryRandomAccessData(bytes);
            segments.Add(new SequentialMediaSegment(
                index,
                SequentialSegmentKind.DataBlock,
                bytes.Length,
                elapsed,
                duration,
                direction: SequentialTravelDirection.Forward,
                dataRange: new MediaDataRange(0, bytes.Length, MediaDataRangeKind.Stored, source, 0),
                metadata: new Dictionary<string, string>(StringComparer.Ordinal)
                {
                    [UefConstants.ChunkIdMetadataKey] = UefConstants.ImplicitData.ToString("x4", CultureInfo.InvariantCulture),
                    [UefConstants.ReconstructionMetadataKey] = bool.TrueString
                }));
            elapsed += duration;
        }
        return new SequentialMediaImageRepresentation(blocks.Sum(block => (long)block.Length), elapsed, segments);
    }

    private static SequentialMediaImageRepresentation EncodeWave(IReadOnlyList<byte[]> blocks, IReadOnlyDictionary<string, string> parameters)
    {
        PcmSampleFunctions.TryReadSampleRate(parameters, out var sampleRate);
        var samples = new List<short>();
        var level = UefConstants.PcmAmplitude;
        for (var index = 0; index < blocks.Count; index++)
        {
            if (index > 0) PcmSampleFunctions.AppendSilence(samples, sampleRate, UefConstants.InterBlockGapSeconds);
            FskSerialFunctions.AppendPcmCarrier(
                samples,
                ref level,
                sampleRate,
                UefConstants.DefaultBaudRate,
                UefConstants.AcornZeroFrequency,
                UefConstants.AcornOneFrequency,
                index == 0 ? UefConstants.InitialCarrierSeconds : UefConstants.InterBlockCarrierSeconds);
            foreach (var value in blocks[index])
                FskSerialFunctions.AppendPcmFrame( samples, ref level, sampleRate, UefConstants.DefaultBaudRate, UefConstants.AcornZeroFrequency, UefConstants.AcornOneFrequency, UefConstants.AcornDataBitsPerFrame, UefConstants.AcornStopBitsPerFrame, value);
        }

        var pcm = new byte[samples.Count * sizeof(short)];
        for (var index = 0; index < samples.Count; index++)
            BinaryPrimitives.WriteInt16LittleEndian(pcm.AsSpan(index * sizeof(short)), samples[index]);
        var source = new MemoryRandomAccessData(pcm);
        var duration = TimeSpan.FromSeconds(samples.Count / (double)sampleRate);
        var segment = new SequentialMediaSegment(
            0,
            SequentialSegmentKind.Samples,
            samples.Count,
            TimeSpan.Zero,
            duration,
            channelNumber: 0,
            direction: SequentialTravelDirection.Forward,
            dataRange: new MediaDataRange(0, pcm.Length, MediaDataRangeKind.Stored, source, 0),
            metadata: new Dictionary<string, string>(StringComparer.Ordinal)
            {
                ["channel"] = "0",
                ["interleaved"] = bool.TrueString,
                ["blockAlign"] = sizeof(short).ToString(CultureInfo.InvariantCulture),
                ["sampleRate"] = sampleRate.ToString(CultureInfo.InvariantCulture),
                ["bitsPerSample"] = UefConstants.PcmBitsPerSample.ToString(CultureInfo.InvariantCulture),
                [UefConstants.ReconstructionMetadataKey] = bool.TrueString
            });
        return new SequentialMediaImageRepresentation(pcm.Length, duration, [segment]);
    }

    private static bool TryBuildBlock(SequentialDecodedBlock block, out byte[] bytes)
    {
        bytes = [];
        if (block.Data.Length > UefConstants.AcornMaximumDataLength
            || !block.Metadata.TryGetValue(UefConstants.FileNameMetadataKey, out var fileName)
            || string.IsNullOrEmpty(fileName)
            || fileName.Length > UefConstants.AcornMaximumFileNameLength
            || fileName.Any(character => character > 0x7f)
            || !TryReadHexUInt32(block.Metadata, UefConstants.LoadAddressMetadataKey, out var loadAddress)
            || !TryReadHexUInt32(block.Metadata, UefConstants.ExecutionAddressMetadataKey, out var executionAddress)
            || !TryReadUInt16(block.Metadata, UefConstants.BlockNumberMetadataKey, out var blockNumber)
            || !TryReadHexByte(block.Metadata, UefConstants.FlagsMetadataKey, out var flags)
            || !TryReadHexUInt32(block.Metadata, UefConstants.NextAddressMetadataKey, out var nextAddress))
            return false;

        var name = System.Text.Encoding.ASCII.GetBytes(fileName);
        var headerLength = name.Length + 1
            + UefConstants.AcornLoadAddressLength
            + UefConstants.AcornExecutionAddressLength
            + UefConstants.AcornBlockNumberLength
            + UefConstants.AcornDataLengthFieldLength
            + UefConstants.AcornFlagsLength
            + UefConstants.AcornNextAddressLength;
        bytes = new byte[1 + headerLength + UefConstants.AcornChecksumLength + block.Data.Length + UefConstants.AcornChecksumLength];
        bytes[0] = UefConstants.AcornBlockSync;
        name.CopyTo(bytes, 1);
        var cursor = 1 + name.Length + 1;
        BinaryPrimitives.WriteUInt32LittleEndian(bytes.AsSpan(cursor), loadAddress);
        cursor += UefConstants.AcornLoadAddressLength;
        BinaryPrimitives.WriteUInt32LittleEndian(bytes.AsSpan(cursor), executionAddress);
        cursor += UefConstants.AcornExecutionAddressLength;
        BinaryPrimitives.WriteUInt16LittleEndian(bytes.AsSpan(cursor), blockNumber);
        cursor += UefConstants.AcornBlockNumberLength;
        BinaryPrimitives.WriteUInt16LittleEndian(bytes.AsSpan(cursor), checked((ushort)block.Data.Length));
        cursor += UefConstants.AcornDataLengthFieldLength;
        bytes[cursor++] = flags;
        BinaryPrimitives.WriteUInt32LittleEndian(bytes.AsSpan(cursor), nextAddress);
        cursor += UefConstants.AcornNextAddressLength;
        var headerChecksum = Crc16Calculator.Compute(bytes.AsSpan(1, headerLength).ToArray(), UefConstants.AcornChecksumPolynomial, UefConstants.AcornChecksumInitialValue);
        BinaryPrimitives.WriteUInt16BigEndian(bytes.AsSpan(cursor), headerChecksum);
        cursor += UefConstants.AcornChecksumLength;
        block.Data.Span.CopyTo(bytes.AsSpan(cursor));
        var dataChecksum = Crc16Calculator.Compute(block.Data.ToArray(), UefConstants.AcornChecksumPolynomial, UefConstants.AcornChecksumInitialValue);
        BinaryPrimitives.WriteUInt16BigEndian(bytes.AsSpan(cursor + block.Data.Length), dataChecksum);
        return true;
    }

    private static bool TryReadHexUInt32(IReadOnlyDictionary<string, string> metadata, string key, out uint value)
    {
        value = 0;
        return metadata.TryGetValue(key, out var text) && uint.TryParse(text, NumberStyles.HexNumber, CultureInfo.InvariantCulture, out value);
    }

    private static bool TryReadHexByte(IReadOnlyDictionary<string, string> metadata, string key, out byte value)
    {
        value = 0;
        return metadata.TryGetValue(key, out var text) && byte.TryParse(text, NumberStyles.HexNumber, CultureInfo.InvariantCulture, out value);
    }

    private static bool TryReadUInt16(IReadOnlyDictionary<string, string> metadata, string key, out ushort value)
    {
        value = 0;
        return metadata.TryGetValue(key, out var text) && ushort.TryParse(text, NumberStyles.None, CultureInfo.InvariantCulture, out value);
    }
}

using System.Buffers.Binary;
using System.Collections.Frozen;
using System.IO;
using System.Text;
using GWGUI.MediaEngine.Constants;
using GWGUI.MediaEngine.Contracts;
using GWGUI.MediaEngine.Enums;
using GWGUI.MediaEngine.Images.Formats.Tape.Amstrad;
using GWGUI.MediaEngine.Images.Formats.Tape.Tzx;
using GWGUI.MediaEngine.Images.Models.Sequential;
using GWGUI.MediaEngine.Images.Reading.Sources;
using GWGUI.MediaEngine.Images.Reading.Recognition;
using GWGUI.MediaEngine.Interfaces.Encoding;

namespace GWGUI.MediaEngine.Images.Writing.Encoding.Sequential.Amstrad;

/// <summary>Encodes CPC firmware file blocks with their native CRC and timing as CDT/TZX or PCM audio.</summary>
public sealed class AmstradCpcTapeEncoder : ISequentialMediaEncoder
{
    private const int DefaultSampleRate = 44100;
    private static readonly IReadOnlySet<string> SupportedFormats = new[] { TapeImageFormatIds.Tzx, TapeImageFormatIds.Wav, TapeImageFormatIds.Voc }.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
    private static readonly IReadOnlySet<string> SupportedMachines = new[] { DiskSystemIds.Amstrad }.ToFrozenSet(StringComparer.OrdinalIgnoreCase);

    public string Id => AmstradCpcTapeConstants.EncoderId;
    public IReadOnlySet<string> FormatIds => SupportedFormats;
    public IReadOnlySet<string> MachineIds => SupportedMachines;

    public bool CanEncode(SequentialEncodeRequest request) => SupportedFormats.Contains(request.TargetFormatId) && SupportedMachines.Contains(request.MachineId) && request.Blocks.Count > 0 && request.Blocks.All(block => block.Data.Length is > 0 and <= 2048) && request.RetainedSegments.Count == 0;

    public Task<SequentialMediaImageRepresentation> EncodeAsync(SequentialEncodeRequest request, CancellationToken cancellationToken = default)
    {
        if (!CanEncode(request))
            throw new InvalidDataException("CPC cassette encoding requires one or more decoded file blocks of at most 2048 bytes.");
        cancellationToken.ThrowIfCancellationRequested();

        var records = BuildRecords(request.Blocks);
        return Task.FromResult(request.TargetFormatId.Equals(TapeImageFormatIds.Tzx, StringComparison.OrdinalIgnoreCase) ? EncodeTzx(records) : EncodePcm(records, ReadSampleRate(request.Parameters)));
    }

    private static IReadOnlyList<byte[]> BuildRecords(IReadOnlyList<SequentialDecodedBlock> blocks)
    {
        var records = new List<byte[]>(blocks.Count * 2);
        for (var index = 0; index < blocks.Count; index++)
        {
            var block = blocks[index];
            var data = block.Data.ToArray();
            var fileName = ReadText(block.Metadata, "fileName", $"BLOCK{index + 1:D3}");
            var firstBlock = index == 0 || !HasSameFileName(blocks[index - 1], fileName);
            var lastBlock = index == blocks.Count - 1 || !HasSameFileName(blocks[index + 1], fileName);
            var header = new byte[AmstradCpcTapeConstants.SegmentDataLength];
            WriteName(header, fileName);
            header[AmstradCpcTapeConstants.BlockNumberOffset] = ReadByte(block.Metadata, "blockNumber", checked((byte)(index + 1)));
            header[AmstradCpcTapeConstants.LastBlockOffset] = ReadBoolean(block.Metadata, "lastBlock", lastBlock) ? (byte)0xff : (byte)0;
            header[AmstradCpcTapeConstants.FileTypeOffset] = ReadByte(block.Metadata, "fileType", 2);
            BinaryPrimitives.WriteUInt16LittleEndian(header.AsSpan(AmstradCpcTapeConstants.DataLengthOffset), checked((ushort)data.Length));
            BinaryPrimitives.WriteUInt16LittleEndian(header.AsSpan(AmstradCpcTapeConstants.DataLocationOffset), ReadUInt16(block.Metadata, "dataLocation"));
            header[AmstradCpcTapeConstants.FirstBlockOffset] = ReadBoolean(block.Metadata, "firstBlock", firstBlock) ? (byte)0xff : (byte)0;
            BinaryPrimitives.WriteUInt16LittleEndian(header.AsSpan(AmstradCpcTapeConstants.LogicalLengthOffset), ReadUInt16(block.Metadata, "logicalLength", checked((ushort)data.Length)));
            BinaryPrimitives.WriteUInt16LittleEndian(header.AsSpan(AmstradCpcTapeConstants.EntryAddressOffset), ReadUInt16(block.Metadata, "entryAddress"));
            records.Add(BuildRecord(AmstradCpcTapeConstants.HeaderSync, header));
            records.Add(BuildRecord(AmstradCpcTapeConstants.DataSync, data));
        }
        return records;
    }

    private static bool HasSameFileName(SequentialDecodedBlock block, string fileName) => block.Metadata.TryGetValue("fileName", out var candidate) && string.Equals(candidate, fileName, StringComparison.Ordinal);

    private static byte[] BuildRecord(byte sync, ReadOnlySpan<byte> data)
    {
        var segmentCount = Math.Max(1, (data.Length + AmstradCpcTapeConstants.SegmentDataLength - 1) / AmstradCpcTapeConstants.SegmentDataLength);
        var encoded = new byte[1 + segmentCount * (AmstradCpcTapeConstants.SegmentDataLength + AmstradCpcTapeConstants.SegmentCrcLength) + AmstradCpcTapeConstants.TrailerByteCount];
        encoded[0] = sync;
        for (var segmentIndex = 0; segmentIndex < segmentCount; segmentIndex++)
        {
            var offset = segmentIndex * AmstradCpcTapeConstants.SegmentDataLength;
            var count = Math.Min(AmstradCpcTapeConstants.SegmentDataLength, data.Length - offset);
            var destinationOffset = 1 + segmentIndex * (AmstradCpcTapeConstants.SegmentDataLength + AmstradCpcTapeConstants.SegmentCrcLength);
            if (count > 0) data.Slice(offset, count).CopyTo(encoded.AsSpan(destinationOffset));
            var segmentData = encoded.AsSpan(destinationOffset, AmstradCpcTapeConstants.SegmentDataLength);
            BinaryPrimitives.WriteUInt16BigEndian(encoded.AsSpan(destinationOffset + AmstradCpcTapeConstants.SegmentDataLength), unchecked((ushort)~ComputeCrc(segmentData)));
        }
        encoded.AsSpan(encoded.Length - AmstradCpcTapeConstants.TrailerByteCount).Fill(AmstradCpcTapeConstants.TrailerByte);
        return encoded;
    }

    private static SequentialMediaImageRepresentation EncodeTzx(IReadOnlyList<byte[]> records)
    {
        var segments = records.Select((record, index) =>
        {
            var payload = CreateTurboPayload(record);
            var source = new MemoryRandomAccessData(payload);
            return new SequentialMediaSegment(
                index,
                SequentialSegmentKind.DataBlock,
                payload.Length,
                dataRange: new MediaDataRange(0, payload.Length, MediaDataRangeKind.Stored, source, 0),
                metadata: new Dictionary<string, string>(StringComparer.Ordinal)
                {
                    [TzxConstants.BlockIdMetadataKey] = TzxConstants.TurboSpeedData.ToString("x2", System.Globalization.CultureInfo.InvariantCulture),
                    ["payloadLength"] = payload.Length.ToString(System.Globalization.CultureInfo.InvariantCulture),
                    ["known"] = bool.TrueString,
                    ["reconstructedSignal"] = bool.TrueString
                });
        }).ToArray();
        return new SequentialMediaImageRepresentation(segments.Sum(segment => segment.Length ?? 0), segments: segments);
    }

    private static SequentialMediaImageRepresentation EncodePcm(IReadOnlyList<byte[]> records, int sampleRate)
    {
        var samples = new List<short>();
        short level = AmstradCpcTapeConstants.PcmAmplitude;
        foreach (var record in records)
        {
            for (var index = 0; index < sampleRate; index++) samples.Add(0);
            AddPulses(samples, ref level, AmstradCpcTapeConstants.OnePulseTStates, AmstradCpcTapeConstants.PilotPulseCount, sampleRate);
            AddPulses(samples, ref level, AmstradCpcTapeConstants.ZeroPulseTStates, 2, sampleRate);
            foreach (var value in record)
                for (var bit = 7; bit >= 0; bit--)
                    AddPulses(samples, ref level, (value & (1 << bit)) == 0 ? AmstradCpcTapeConstants.ZeroPulseTStates : AmstradCpcTapeConstants.OnePulseTStates, 2, sampleRate);
        }
        for (var index = 0; index < sampleRate; index++) samples.Add(0);

        var pcm = new byte[samples.Count * sizeof(short)];
        for (var index = 0; index < samples.Count; index++)
            BinaryPrimitives.WriteInt16LittleEndian(pcm.AsSpan(index * sizeof(short)), samples[index]);
        var source = new MemoryRandomAccessData(pcm);
        var duration = TimeSpan.FromSeconds(samples.Count / (double)sampleRate);
        var segment = new SequentialMediaSegment(
            0,
            SequentialSegmentKind.Samples,
            samples.Count,
            TimeSpan.Zero,
            duration,
            channelNumber: 0,
            direction: SequentialTravelDirection.Forward,
            dataRange: new MediaDataRange(0, pcm.Length, MediaDataRangeKind.Stored, source, 0),
            metadata: new Dictionary<string, string>(StringComparer.Ordinal)
            {
                ["channel"] = "0",
                ["interleaved"] = bool.TrueString,
                ["blockAlign"] = sizeof(short).ToString(System.Globalization.CultureInfo.InvariantCulture),
                ["sampleRate"] = sampleRate.ToString(System.Globalization.CultureInfo.InvariantCulture),
                ["bitsPerSample"] = AmstradCpcTapeConstants.PcmBitsPerSample.ToString(System.Globalization.CultureInfo.InvariantCulture),
                ["reconstructedSignal"] = bool.TrueString
            });
        return new SequentialMediaImageRepresentation(pcm.Length, duration, [segment]);
    }

    private static byte[] CreateTurboPayload(ReadOnlySpan<byte> data)
    {
        var payload = new byte[18 + data.Length];
        BinaryPrimitives.WriteUInt16LittleEndian(payload, AmstradCpcTapeConstants.OnePulseTStates);
        BinaryPrimitives.WriteUInt16LittleEndian(payload.AsSpan(2), AmstradCpcTapeConstants.ZeroPulseTStates);
        BinaryPrimitives.WriteUInt16LittleEndian(payload.AsSpan(4), AmstradCpcTapeConstants.ZeroPulseTStates);
        BinaryPrimitives.WriteUInt16LittleEndian(payload.AsSpan(6), AmstradCpcTapeConstants.ZeroPulseTStates);
        BinaryPrimitives.WriteUInt16LittleEndian(payload.AsSpan(8), AmstradCpcTapeConstants.OnePulseTStates);
        BinaryPrimitives.WriteUInt16LittleEndian(payload.AsSpan(10), AmstradCpcTapeConstants.PilotPulseCount);
        payload[12] = AmstradCpcTapeConstants.UsedBitsInLastByte;
        BinaryPrimitives.WriteUInt16LittleEndian(payload.AsSpan(13), AmstradCpcTapeConstants.PauseMilliseconds);
        GWGUI.MediaEngine.Functions.BitPrimitives.WriteUInt24LittleEndian(payload.AsSpan(15), data.Length);
        data.CopyTo(payload.AsSpan(18));
        return payload;
    }

    private static void AddPulses(List<short> samples, ref short level, ushort tStates, int count, int sampleRate)
        => GWGUI.MediaEngine.Functions.PcmSampleFunctions.AppendPulses(samples, ref level, tStates, count, sampleRate, TzxConstants.TStatesPerSecond);

    private static void WriteName(Span<byte> header, string name)
    {
        var bytes = System.Text.Encoding.Latin1.GetBytes(name);
        bytes.AsSpan(0, Math.Min(bytes.Length, AmstradCpcTapeConstants.FileNameLength)).CopyTo(header[AmstradCpcTapeConstants.FileNameOffset..]);
    }

    private static ushort ComputeCrc(ReadOnlySpan<byte> data)
        => GWGUI.MediaEngine.Functions.Crc16Calculator.ComputeSpan(data, AmstradCpcTapeConstants.CrcPolynomial, AmstradCpcTapeConstants.CrcSeed);

    private static int ReadSampleRate(IReadOnlyDictionary<string, string> metadata) => GWGUI.MediaEngine.Functions.PcmSampleFunctions.TryReadSampleRate(metadata, out var sampleRate) ? sampleRate : DefaultSampleRate;

    private static string ReadText(IReadOnlyDictionary<string, string> metadata, string key, string defaultValue) => metadata.TryGetValue(key, out var value) && !string.IsNullOrWhiteSpace(value) ? value : defaultValue;

    private static byte ReadByte(IReadOnlyDictionary<string, string> metadata, string key, byte defaultValue) =>
        metadata.TryGetValue(key, out var value) && byte.TryParse(value, System.Globalization.NumberStyles.None, System.Globalization.CultureInfo.InvariantCulture, out var parsed) ? parsed : defaultValue;

    private static ushort ReadUInt16(IReadOnlyDictionary<string, string> metadata, string key, ushort defaultValue = 0) =>
        metadata.TryGetValue(key, out var value) && ushort.TryParse(value, System.Globalization.NumberStyles.None, System.Globalization.CultureInfo.InvariantCulture, out var parsed) ? parsed : defaultValue;

    private static bool ReadBoolean(IReadOnlyDictionary<string, string> metadata, string key, bool defaultValue) => metadata.TryGetValue(key, out var value) && bool.TryParse(value, out var parsed) ? parsed : defaultValue;
}

